-- MTH 121 (Elementary Mathematics II, UNN) practice questions for the CBT feature.
-- 223 questions across 42 topics. The original 159 (functions, limits,
-- continuity, differentiation, integration) come from real worked calculus
-- questions supplied by the user; 64 more were added by cross-referencing the
-- official UNN Mathematics department textbook ("Introductory University
-- Mathematics 2: Calculus", Amazigo et al.) and the official UNN MTH121
-- course outline, covering real gaps against both: the derivative as a
-- first-principles limit, tangents/normals, velocity/acceleration, higher
-- order derivatives, extrema tests (first/second derivative test), curve
-- sketching (symmetry, intercepts, asymptotes), one-sided and infinite
-- limits, types of discontinuity, the inverse of a function, the shell
-- method, and partial fractions. Every question's explanation is a genuine
-- sympy-verified step-by-step derivation (not just a name-the-rule
-- statement) -- see the "gen_explanations.py" / "new_topics*.py" generation
-- scripts. Every field (question, options, explanation) is fully rendered in
-- LaTeX: every word is individually wrapped in its own $...$ span (math as
-- real notation, prose in \text{}), joined by literal spaces so MathText
-- can still line-wrap normally.
--
-- This revision also fixes three real rendering bugs found by auditing the
-- previously-shipped output (not just testing that it parsed): (1) when a
-- long formula was split across several $...$ spans for line-wrapping, the
-- connecting '=' / '+' / '-' between the pieces was left as bare, unwrapped
-- text instead of its own math span; (2) "y = ... about the x-axis ..." style
-- question stems swallowed the whole descriptive clause into math mode instead
-- of stopping at "about"; (3) stray Unicode math glyphs (x^2 written as x²,
-- sqrt(x) missing its backslash, bare "∞"/"√"/inequality signs) that fell
-- outside every structural pattern the converter recognised were left as raw
-- Unicode text instead of proper LaTeX. See latexify.py / full_latexify.py in
-- the generation pipeline for the fixes.
--
-- One question was dropped: the definite integral of 1/[(x-1)(x+2)] from 0 to 1
-- has a singularity at x=1 (the upper bound), so it diverges and none of the
-- supplied answer choices are mathematically valid.
--
-- cbt_questions has no course_code column, so the MTH 121 link lives in
-- subject_name. is_general = false and faculty is pinned to 'Faculty of
-- Physical Sciences' so only students in that faculty see this paper.

delete from public.cbt_questions where subject_id = 'mth-121-calculus';

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general)
values
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = 2x-3$$\textrm{,}$ $g(x) = x^2+1$$\textrm{,}$ $\textrm{find}$ $(f \circ g)(2)$$\textrm{.}$', '["$5$", "$7$", "$6$", "$2$"]'::jsonb, 1, '$(f \circ g)(2) = f(g(2))$$\textrm{.}$ $\textrm{First}$ $\textrm{find}$ $g(2)$ $\textrm{by}$ $\textrm{substituting}$ $x=2$ $\textrm{into}$ $g(x) = x^{2} + 1$$\textrm{:}$ $g(2) = 2^{2} + 1 = 5$$\textrm{.}$ $\textrm{Then}$ $\textrm{substitute}$ $g(2) = 5$ $\textrm{into}$ $f(x) = 2 x - 3$$\textrm{:}$ $f(5) = 2 \cdot 5 - 3 = 7$$\textrm{.}$ $\textrm{So}$ $(f \circ g)(2) = 7$$\textrm{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = x^2$$\textrm{,}$ $g(x) = 3x-1$$\textrm{,}$ $\textrm{find}$ $(f \circ g)(1)$$\textrm{.}$', '["$5$", "$2$", "$4$", "$3$"]'::jsonb, 2, '$(f \circ g)(1) = f(g(1))$$\textrm{.}$ $\textrm{First}$ $\textrm{find}$ $g(1)$ $\textrm{by}$ $\textrm{substituting}$ $x=1$ $\textrm{into}$ $g(x) = 3 x - 1$$\textrm{:}$ $g(1) = 3 \cdot 1 - 1 = 2$$\textrm{.}$ $\textrm{Then}$ $\textrm{substitute}$ $g(1) = 2$ $\textrm{into}$ $f(x) = x^{2}$$\textrm{:}$ $f(2) = 2^{2} = 4$$\textrm{.}$ $\textrm{So}$ $(f \circ g)(1) = 4$$\textrm{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = |x|$$\textrm{,}$ $g(x) = 2x-5$$\textrm{,}$ $\textrm{find}$ $(f \circ g)(1)$$\textrm{.}$', '["$3$", "$-2$", "$-3$", "$4$"]'::jsonb, 0, '$(f \circ g)(1) = f(g(1))$$\textrm{.}$ $\textrm{First}$ $\textrm{find}$ $g(1)$ $\textrm{by}$ $\textrm{substituting}$ $x=1$ $\textrm{into}$ $g(x) = 2 x - 5$$\textrm{:}$ $g(1) = 2 \cdot 1 - 5 = -3$$\textrm{.}$ $\textrm{Then}$ $\textrm{substitute}$ $g(1) = -3$ $\textrm{into}$ $f(x) = \left|{x}\right|$$\textrm{:}$ $f(-3) = \left|{-3}\right| = 3$$\textrm{.}$ $\textrm{So}$ $(f \circ g)(1) = 3$$\textrm{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = 3x+4$$\textrm{,}$ $g(x) = x^2-2x$$\textrm{,}$ $\textrm{find}$ $(f \circ g)(3)$$\textrm{.}$', '["$16$", "$3$", "$13$", "$143$"]'::jsonb, 2, '$(f \circ g)(3) = f(g(3))$$\textrm{.}$ $\textrm{First}$ $\textrm{find}$ $g(3)$ $\textrm{by}$ $\textrm{substituting}$ $x=3$ $\textrm{into}$ $g(x) = x^{2} - 2 x$$\textrm{:}$ $g(3) = 3^{2} - 2 \cdot 3 = 3$$\textrm{.}$ $\textrm{Then}$ $\textrm{substitute}$ $g(3) = 3$ $\textrm{into}$ $f(x) = 3 x + 4$$\textrm{:}$ $f(3) = 3 \cdot 3 + 4 = 13$$\textrm{.}$ $\textrm{So}$ $(f \circ g)(3) = 13$$\textrm{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = x^2-1$$\textrm{,}$ $g(x) = x+2$$\textrm{,}$ $\textrm{find}$ $(f \circ g)(-1)$$\textrm{.}$', '["$-1$", "$1$", "$2$", "$0$"]'::jsonb, 3, '$(f \circ g)(-1) = f(g(-1))$$\textrm{.}$ $\textrm{First}$ $\textrm{find}$ $g(-1)$ $\textrm{by}$ $\textrm{substituting}$ $x=-1$ $\textrm{into}$ $g(x) = x + 2$$\textrm{:}$ $g(-1) = -1 + 2 = 1$$\textrm{.}$ $\textrm{Then}$ $\textrm{substitute}$ $g(-1) = 1$ $\textrm{into}$ $f(x) = x^{2} - 1$$\textrm{:}$ $f(1) = 1^{2} - 1 = 0$$\textrm{.}$ $\textrm{So}$ $(f \circ g)(-1) = 0$$\textrm{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = 5-x$$\textrm{,}$ $g(x) = x^2$$\textrm{,}$ $\textrm{find}$ $(f \circ g)(3)$$\textrm{.}$', '["$9$", "$4$", "$11$", "$-4$"]'::jsonb, 3, '$(f \circ g)(3) = f(g(3))$$\textrm{.}$ $\textrm{First}$ $\textrm{find}$ $g(3)$ $\textrm{by}$ $\textrm{substituting}$ $x=3$ $\textrm{into}$ $g(x) = x^{2}$$\textrm{:}$ $g(3) = 3^{2} = 9$$\textrm{.}$ $\textrm{Then}$ $\textrm{substitute}$ $g(3) = 9$ $\textrm{into}$ $f(x) = 5 - x$$\textrm{:}$ $f(9) = 5 - 9 = -4$$\textrm{.}$ $\textrm{So}$ $(f \circ g)(3) = -4$$\textrm{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = x^3$$\textrm{,}$ $g(x) = x-1$$\textrm{,}$ $\textrm{find}$ $(f \circ g)(2)$$\textrm{.}$', '["$7$", "$1$", "$2$", "$9$"]'::jsonb, 1, '$(f \circ g)(2) = f(g(2))$$\textrm{.}$ $\textrm{First}$ $\textrm{find}$ $g(2)$ $\textrm{by}$ $\textrm{substituting}$ $x=2$ $\textrm{into}$ $g(x) = x - 1$$\textrm{:}$ $g(2) = 2 - 1 = 1$$\textrm{.}$ $\textrm{Then}$ $\textrm{substitute}$ $g(2) = 1$ $\textrm{into}$ $f(x) = x^{3}$$\textrm{:}$ $f(1) = 1^{3} = 1$$\textrm{.}$ $\textrm{So}$ $(f \circ g)(2) = 1$$\textrm{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = 4-2x$$\textrm{,}$ $g(x) = x^2+3$$\textrm{,}$ $\textrm{find}$ $(f \circ g)(1)$$\textrm{.}$', '["$6$", "$4$", "$7$", "$-4$"]'::jsonb, 3, '$(f \circ g)(1) = f(g(1))$$\textrm{.}$ $\textrm{First}$ $\textrm{find}$ $g(1)$ $\textrm{by}$ $\textrm{substituting}$ $x=1$ $\textrm{into}$ $g(x) = x^{2} + 3$$\textrm{:}$ $g(1) = 1^{2} + 3 = 4$$\textrm{.}$ $\textrm{Then}$ $\textrm{substitute}$ $g(1) = 4$ $\textrm{into}$ $f(x) = 4 - 2 x$$\textrm{:}$ $f(4) = 4 - 2 \cdot 4 = -4$$\textrm{.}$ $\textrm{So}$ $(f \circ g)(1) = -4$$\textrm{.}$', 'Composition of Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = 2x+1$$\textrm{,}$ $g(x) = x^2$$\textrm{,}$ $\textrm{find}$ $(f+g)(3)$$\textrm{.}$', '["$-2$", "$63$", "$7$", "$16$"]'::jsonb, 3, '$(f+g)(3) = f(3) + g(3)$$\textrm{.}$ $\textrm{Substituting}$ $x=3$$\textrm{:}$ $f(3) = 2 \cdot 3 + 1 = 7$ $\textrm{and}$ $g(3) = 3^{2} = 9$$\textrm{,}$ $\textrm{so}$ $(f+g)(3) = 7 + 9 = 16$$\textrm{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = 2x+1$$\textrm{,}$ $g(x) = x^2$$\textrm{,}$ $\textrm{find}$ $(f \cdot g)(3)$$\textrm{.}$', '["$16$", "$63$", "$-2$", "$9$"]'::jsonb, 1, '$(f \cdot g)(3) = f(3) \cdot g(3)$$\textrm{.}$ $\textrm{Substituting}$ $x=3$$\textrm{:}$ $f(3) = 2 \cdot 3 + 1 = 7$ $\textrm{and}$ $g(3) = 3^{2} = 9$$\textrm{,}$ $\textrm{so}$ $(f \cdot g)(3) = 7 \cdot 9 = 63$$\textrm{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = x^2-4$$\textrm{,}$ $g(x) = x+2$$\textrm{,}$ $\textrm{find}$ $(f+g)(1)$$\textrm{.}$', '["$-6$", "$0$", "$-9$", "$-3$"]'::jsonb, 1, '$(f+g)(1) = f(1) + g(1)$$\textrm{.}$ $\textrm{Substituting}$ $x=1$$\textrm{:}$ $f(1) = 1^{2} - 4 = -3$ $\textrm{and}$ $g(1) = 1 + 2 = 3$$\textrm{,}$ $\textrm{so}$ $(f+g)(1) = -3 + 3 = 0$$\textrm{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = x^2-4$$\textrm{,}$ $g(x) = x+2$$\textrm{,}$ $\textrm{find}$ $(f \cdot g)(1)$$\textrm{.}$', '["$-9$", "$-6$", "$3$", "$0$"]'::jsonb, 0, '$(f \cdot g)(1) = f(1) \cdot g(1)$$\textrm{.}$ $\textrm{Substituting}$ $x=1$$\textrm{:}$ $f(1) = 1^{2} - 4 = -3$ $\textrm{and}$ $g(1) = 1 + 2 = 3$$\textrm{,}$ $\textrm{so}$ $(f \cdot g)(1) = -3 \cdot 3 = -9$$\textrm{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = 3x$$\textrm{,}$ $g(x) = x-5$$\textrm{,}$ $\textrm{find}$ $(f+g)(4)$$\textrm{.}$', '["$-12$", "$11$", "$12$", "$13$"]'::jsonb, 1, '$(f+g)(4) = f(4) + g(4)$$\textrm{.}$ $\textrm{Substituting}$ $x=4$$\textrm{:}$ $f(4) = 3 \cdot 4 = 12$ $\textrm{and}$ $g(4) = 4 - 5 = -1$$\textrm{,}$ $\textrm{so}$ $(f+g)(4) = 12 + -1 = 11$$\textrm{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = 3x$$\textrm{,}$ $g(x) = x-5$$\textrm{,}$ $\textrm{find}$ $(f \cdot g)(4)$$\textrm{.}$', '["$-12$", "$13$", "$-1$", "$11$"]'::jsonb, 0, '$(f \cdot g)(4) = f(4) \cdot g(4)$$\textrm{.}$ $\textrm{Substituting}$ $x=4$$\textrm{:}$ $f(4) = 3 \cdot 4 = 12$ $\textrm{and}$ $g(4) = 4 - 5 = -1$$\textrm{,}$ $\textrm{so}$ $(f \cdot g)(4) = 12 \cdot -1 = -12$$\textrm{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = x^2+2$$\textrm{,}$ $g(x) = 2x-1$$\textrm{,}$ $\textrm{find}$ $(f+g)(2)$$\textrm{.}$', '["$18$", "$6$", "$3$", "$9$"]'::jsonb, 3, '$(f+g)(2) = f(2) + g(2)$$\textrm{.}$ $\textrm{Substituting}$ $x=2$$\textrm{:}$ $f(2) = 2^{2} + 2 = 6$ $\textrm{and}$ $g(2) = 2 \cdot 2 - 1 = 3$$\textrm{,}$ $\textrm{so}$ $(f+g)(2) = 6 + 3 = 9$$\textrm{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Given}$ $f(x) = x^2+2$$\textrm{,}$ $g(x) = 2x-1$$\textrm{,}$ $\textrm{find}$ $(f \cdot g)(2)$$\textrm{.}$', '["$18$", "$19$", "$3$", "$9$"]'::jsonb, 0, '$(f \cdot g)(2) = f(2) \cdot g(2)$$\textrm{.}$ $\textrm{Substituting}$ $x=2$$\textrm{:}$ $f(2) = 2^{2} + 2 = 6$ $\textrm{and}$ $g(2) = 2 \cdot 2 - 1 = 3$$\textrm{,}$ $\textrm{so}$ $(f \cdot g)(2) = 6 \cdot 3 = 18$$\textrm{.}$', 'Operations on Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{If}$ $f(x) = 3x-4$$\textrm{,}$ $\textrm{find}$ $f^{-1}(5)$$\textrm{.}$', '["$27$", "$1/3$", "$11$", "$3$"]'::jsonb, 3, '$\textrm{To}$ $\textrm{find}$ $f^{-1}(5)$$\textrm{,}$ $\textrm{solve}$ $f(x) = 5$ $\textrm{for}$ $x$$\textrm{:}$ $3 x - 4 = 5$$\textrm{.}$ $\textrm{Rearranging}$ $\textrm{gives}$ $x = 3$$\textrm{,}$ $\textrm{so}$ $f^{-1}(5) = 3$$\textrm{.}$', 'The Inverse of a Function', false),
