  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\lim_{x \to 0} [\sin(4x)/x]$$\textrm{.}$', '["$4$", "$\\textrm{does}$ $\\textrm{not}$ $\\textrm{exist}$", "$1$", "$0$"]'::jsonb, 0, '$\textrm{Rewrite}$ $\dfrac{\sin(4x)}{x}$ $\textrm{as}$ $4 \cdot \dfrac{\sin(4x)}{4x}$$\textrm{.}$ $\textrm{Using}$ $\lim_{x \to 0} \dfrac{\sin(kx)}{kx} = 1$ $\textrm{with}$ $k=4$$\textrm{,}$ $\textrm{the}$ $\textrm{second}$ $\textrm{factor}$ $\textrm{tends}$ $\textrm{to}$ $1$$\textrm{,}$ $\textrm{leaving}$ $\lim_{x \to 0} \dfrac{\sin(4x)}{x}$ $=$ $4 \cdot 1$ $=$ $4$$\textrm{.}$', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\lim_{x \to 0} [\sin(3x)/(5x)]$$\textrm{.}$', '["$3/5$", "$1$", "$0$", "$5/3$"]'::jsonb, 0, '$\textrm{Rewrite}$ $\dfrac{\sin(3x)}{5x}$ $\textrm{as}$ $\frac{3}{5} \cdot \dfrac{\sin(3x)}{3x}$$\textrm{.}$ $\textrm{Using}$ $\lim_{x \to 0} \dfrac{\sin(kx)}{kx} = 1$ $\textrm{with}$ $k=3$$\textrm{,}$ $\textrm{the}$ $\textrm{second}$ $\textrm{factor}$ $\textrm{tends}$ $\textrm{to}$ $1$$\textrm{,}$ $\textrm{leaving}$ $\lim_{x \to 0} \dfrac{\sin(3x)}{5x}$ $=$ $\frac{3}{5} \cdot 1$ $=$ $\frac{3}{5}$$\textrm{.}$', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\lim_{x \to 0} [(1-cos x)/x]$$\textrm{.}$', '["$1$", "$0$", "$\\textrm{does}$ $\\textrm{not}$ $\\textrm{exist}$", "$1/2$"]'::jsonb, 1, '$\textrm{Using}$ $\textrm{the}$ $\textrm{standard}$ $\textrm{limit}$ $\lim_{x \to 0} \dfrac{\cos(x) - 1}{x}$ $=$ $0$ $\textrm{(equivalently}$ $\lim_{x \to 0} \dfrac{1 - \cos(x)}{x}$ $=$ $0$$\textrm{,}$ $\textrm{since}$ $1-\cos x$ $\textrm{is}$ $\textrm{a}$ $\textrm{sign}$ $\textrm{flip}$ $\textrm{of}$ $\cos x - 1$$\textrm{):}$ $\lim_{x \to 0} \frac{1 - \cos{\left(x \right)}}{x}$ $=$ $0$$\textrm{.}$', 'Limits of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\lim_{x \to 0} [x \cdot \sin(1/x)]$ $\textrm{using}$ $\textrm{the}$ $\textrm{Sandwich}$ $\textrm{Theorem.}$', '["$0$", "$1$", "$\\textrm{does}$ $\\textrm{not}$ $\\textrm{exist}$", "$\\infty$"]'::jsonb, 0, '$-1 \leq \sin(1/x) \leq 1$ $\textrm{for}$ $\textrm{every}$ $x \neq 0$$\textrm{,}$ $\textrm{so}$ $\textrm{multiplying}$ $\textrm{through}$ $\textrm{by}$ $|x|$ $\textrm{gives}$ $-|x| \leq x\sin(1/x) \leq |x|$$\textrm{.}$ $\textrm{As}$ $x \to 0$$\textrm{,}$ $\textrm{both}$ $\textrm{bounds}$ $-|x|$ $\textrm{and}$ $|x|$ $\textrm{tend}$ $\textrm{to}$ $0$$\textrm{,}$ $\textrm{so}$ $\textrm{by}$ $\textrm{the}$ $\textrm{Sandwich}$ $\textrm{(Squeeze)}$ $\textrm{Theorem,}$ $\lim_{x \to 0} x\sin(1/x) = 0$$\textrm{.}$', 'Some Theorems on Limits', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{For}$ $f(x) = (x^2-25)/(x-5)$ $\textrm{if}$ $x \neq 5$$\textrm{,}$ $\textrm{and}$ $f(5)$$=10$$\textrm{,}$ $\textrm{is}$ $\textrm{f}$ $\textrm{continuous}$ $\textrm{at}$ $\textrm{x=5?}$', '["$\\textrm{No}$ $\\textrm{—}$ $\\textrm{removable}$ $\\textrm{discontinuity}$", "$\\textrm{No}$ $\\textrm{—}$ $\\textrm{jump}$ $\\textrm{discontinuity}$", "$\\textrm{No}$ $\\textrm{—}$ $\\textrm{essential}$ $\\textrm{discontinuity}$", "$\\textrm{Yes}$ $\\textrm{—}$ $\\textrm{f}$ $\\textrm{is}$ $\\textrm{continuous}$ $\\textrm{at}$ $\\textrm{x=5}$"]'::jsonb, 3, '$\textrm{Simplify:}$ $\frac{x^{2} - 25}{x - 5} = x + 5$ $\textrm{for}$ $x \neq 5$$\textrm{,}$ $\textrm{so}$ $\lim_{x \to 5} f(x) = 5 + 5 = 10$$\textrm{.}$ $\textrm{This}$ $\textrm{equals}$ $\textrm{the}$ $\textrm{given}$ $f(5) = 10$$\textrm{,}$ $\textrm{and}$ $\textrm{since}$ $\textrm{the}$ $\textrm{limit}$ $\textrm{exists}$ $\textrm{and}$ $\textrm{matches}$ $f(5)$$\textrm{,}$ $f$ $\textrm{is}$ $\textrm{continuous}$ $\textrm{at}$ $x=5$$\textrm{.}$', 'Continuous Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{For}$ $f(x) = (x^2-25)/(x-5)$ $\textrm{if}$ $x \neq 5$$\textrm{,}$ $\textrm{and}$ $f(5)$$=7$$\textrm{,}$ $\textrm{is}$ $\textrm{f}$ $\textrm{continuous}$ $\textrm{at}$ $\textrm{x=5?}$', '["$\\textrm{No}$ $\\textrm{—}$ $\\textrm{essential}$ $\\textrm{discontinuity}$", "$\\textrm{Yes}$ $\\textrm{—}$ $\\textrm{f}$ $\\textrm{is}$ $\\textrm{continuous}$ $\\textrm{at}$ $\\textrm{x=5}$", "$\\textrm{No}$ $\\textrm{—}$ $\\textrm{removable}$ $\\textrm{discontinuity}$", "$\\textrm{No}$ $\\textrm{—}$ $\\textrm{jump}$ $\\textrm{discontinuity}$"]'::jsonb, 2, '$\textrm{Simplify:}$ $\frac{x^{2} - 25}{x - 5} = x + 5$ $\textrm{for}$ $x \neq 5$$\textrm{,}$ $\textrm{so}$ $\lim_{x \to 5} f(x) = 5 + 5 = 10$$\textrm{,}$ $\textrm{but}$ $\textrm{the}$ $\textrm{given}$ $f(5) = 7 \neq 10$$\textrm{.}$ $\textrm{The}$ $\textrm{limit}$ $\textrm{exists}$ $\textrm{but}$ $\textrm{does}$ $\textrm{not}$ $\textrm{equal}$ $f(5)$$\textrm{,}$ $\textrm{so}$ $f$ $\textrm{is}$ $\textrm{discontinuous}$ $\textrm{at}$ $x=5$$\textrm{.}$', 'Types of Discontinuities', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = x^5$$\textrm{.}$', '["$5x^5$", "$5x^4$", "$20x^3$", "$x^5$"]'::jsonb, 1, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[x^{5}] = 5 x^{4} = 5 x^{4}$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = 5 x^{4}$$\textrm{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = 3x^4$$\textrm{.}$', '["$12x^3$", "$3x^4$", "$12x^4$", "$36x^2$"]'::jsonb, 0, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[3 \cdot x^{4}]$ $=$ $3 \cdot 4 x^{3}$ $=$ $12 x^{3}$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = 12 x^{3}$$\textrm{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = 7x^3 - 2x^2 + x$$\textrm{.}$', '["$7x^3 - 2x^2 + x$", "$21x^3 - 4x^2 + x$", "$42x - 4$", "$21x^2 - 4x + 1$"]'::jsonb, 3, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[7 \cdot x^{3}]$ $=$ $7 \cdot 3 x^{2}$ $=$ $21 x^{2}$$\textrm{;}$ $\dfrac{d}{dx}[-2 \cdot x^{2}]$ $=$ $-2 \cdot 2 x^{1}$ $=$ $- 4 x$$\textrm{;}$ $\dfrac{d}{dx}[x^{1}] = 1 x^{0} = 1$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = 21 x^{2} - 4 x + 1$$\textrm{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = x^6 - 4x$$\textrm{.}$', '["$30x^4$", "$6x^5 - 4$", "$x^6 - 4x$", "$6x^6 - 4x$"]'::jsonb, 1, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[x^{6}] = 6 x^{5} = 6 x^{5}$$\textrm{;}$ $\dfrac{d}{dx}[-4 \cdot x^{1}]$ $=$ $-4 \cdot 1 x^{0}$ $=$ $-4$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = 6 x^{5} - 4$$\textrm{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = 2x^7 + 5$$\textrm{.}$', '["$14x^6$", "$14x^7$", "$84x^5$", "$2x^7 + 5$"]'::jsonb, 0, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[2 \cdot x^{7}]$ $=$ $2 \cdot 7 x^{6}$ $=$ $14 x^{6}$$\textrm{;}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $\textrm{the}$ $\textrm{constant}$ $5$ $\textrm{is}$ $0$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = 14 x^{6}$$\textrm{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = x^2/2 - 3x$$\textrm{.}$', '["$1$", "$x - 3$", "$x^2/2 - 3x$", "$x^2 - 3x$"]'::jsonb, 1, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[\frac{1}{2} \cdot x^{2}]$ $=$ $\frac{1}{2} \cdot 2 x^{1}$ $=$ $x$$\textrm{;}$ $\dfrac{d}{dx}[-3 \cdot x^{1}]$ $=$ $-3 \cdot 1 x^{0}$ $=$ $-3$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = x - 3$$\textrm{.}$', 'Derivative of the Power Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \sin(x)$$\textrm{.}$', '["$\\cos(x) + 1$", "$\\cos(x)$", "$\\sin(x)$", "$-\\cos(x)$"]'::jsonb, 1, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[\sin(x)] = \cos(x)$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = \cos{\left(x \right)}$$\textrm{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \cos(x)$$\textrm{.}$', '["$\\sin(x)$", "$-\\sin(x)$", "$\\cos(x)$", "$1 - \\sin(x)$"]'::jsonb, 1, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[\cos(x)] = -\sin(x)$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = - \sin{\left(x \right)}$$\textrm{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \tan(x)$$\textrm{.}$', '["$-1/\\cos(x)^2$", "$\\tan(x)$", "$\\cos(x)$", "$\\cos(x)^{-2}$"]'::jsonb, 3, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[\tan{\left(x \right)}]$ $=$ $\tan^{2}{\left(x \right)} + 1$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = 1 + \tan^{2}{\left(x \right)}$$\textrm{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = 3 \sin(x)$$\textrm{.}$', '["$\\cos(x)$", "$-3 \\cos(x)$", "$3 \\cos(x)$", "$3 \\sin(x)$"]'::jsonb, 2, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[3 \cdot \sin(x)]$ $=$ $3 \cdot \cos(x)$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x) = 3 \cos{\left(x \right)}$$\textrm{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \sin(x) + \cos(x)$$\textrm{.}$', '["$-\\sin(x) + \\cos(x)$", "$\\sin(x) - \\cos(x)$", "$\\sin(x) + \\cos(x)$", "$\\cos(x)$"]'::jsonb, 0, '$\textrm{Differentiate}$ $\textrm{term}$ $\textrm{by}$ $\textrm{term:}$ $\dfrac{d}{dx}[\sin(x)] = \cos(x)$$\textrm{;}$ $\dfrac{d}{dx}[\cos(x)] = -\sin(x)$$\textrm{.}$ $\textrm{Summing}$ $\textrm{the}$ $\textrm{terms:}$ $f''(x)$ $=$ $\cos{\left(x \right)}$ $-$ $\sin{\left(x \right)}$$\textrm{.}$', 'Derivatives of Trigonometric Functions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Product}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = x^2 \cdot \sin(x)$$\textrm{.}$', '["$x(x \\cos(x) + 2 \\sin(x))$", "$x^2 \\cos(x)$", "$2x \\cos(x)$", "$2x \\sin(x)$"]'::jsonb, 0, '$\textrm{Product}$ $\textrm{Rule:}$ $(uv)'' = u''v + uv''$$\textrm{.}$ $\textrm{With}$ $u = x^{2}$ $\textrm{and}$ $v = \sin{\left(x \right)}$$\textrm{:}$ $u'' = 2 x$ $\textrm{and}$ $v'' = \cos{\left(x \right)}$$\textrm{.}$ $\textrm{So}$ $f''(x)$ $=$ $u''v + uv''$ $=$ $(2 x)(\sin{\left(x \right)})$ $+$ $(x^{2})(\cos{\left(x \right)})$ $=$ $x \left(x \cos{\left(x \right)} + 2 \sin{\left(x \right)}\right)$$\textrm{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Product}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = x \cdot \cos(x)$$\textrm{.}$', '["$-x \\sin(x)$", "$-x \\sin(x) + \\cos(x)$", "$\\cos(x)$", "$-\\sin(x)$"]'::jsonb, 1, '$\textrm{Product}$ $\textrm{Rule:}$ $(uv)'' = u''v + uv''$$\textrm{.}$ $\textrm{With}$ $u = x$ $\textrm{and}$ $v = \cos{\left(x \right)}$$\textrm{:}$ $u'' = 1$ $\textrm{and}$ $v'' = - \sin{\left(x \right)}$$\textrm{.}$ $\textrm{So}$ $f''(x)$ $=$ $u''v + uv''$ $=$ $(1)(\cos{\left(x \right)})$ $+$ $(x)(- \sin{\left(x \right)})$ $=$ $- x \sin{\left(x \right)}$ $+$ $\cos{\left(x \right)}$$\textrm{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Product}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = x^2 \cdot x + 1$$\textrm{.}$', '["$x^2$", "$2x$", "$2x^2 + 2x$", "$3x^2 + 2x$"]'::jsonb, 3, '$\textrm{Product}$ $\textrm{Rule:}$ $(uv)'' = u''v + uv''$$\textrm{.}$ $\textrm{With}$ $u = x^{2}$ $\textrm{and}$ $v = x + 1$$\textrm{:}$ $u'' = 2 x$ $\textrm{and}$ $v'' = 1$$\textrm{.}$ $\textrm{So}$ $f''(x)$ $=$ $u''v + uv''$ $=$ $(2 x)(x + 1) + (x^{2})(1)$ $=$ $x \left(3 x + 2\right)$$\textrm{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Product}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \sin(x) \cdot \cos(x)$$\textrm{.}$', '["$\\cos(2x)$", "$-\\sin(x)^2$", "$\\cos(x)^2$", "$-\\sin(2x)/2$"]'::jsonb, 0, '$\textrm{Product}$ $\textrm{Rule:}$ $(uv)'' = u''v + uv''$$\textrm{.}$ $\textrm{With}$ $u = \sin{\left(x \right)}$ $\textrm{and}$ $v = \cos{\left(x \right)}$$\textrm{:}$ $u'' = \cos{\left(x \right)}$ $\textrm{and}$ $v'' = - \sin{\left(x \right)}$$\textrm{.}$ $\textrm{So}$ $f''(x)$ $=$ $u''v + uv''$ $=$ $(\cos{\left(x \right)})(\cos{\left(x \right)})$ $+$ $(\sin{\left(x \right)})(- \sin{\left(x \right)})$ $=$ $\cos{\left(2 x \right)}$$\textrm{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Quotient}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = (x)/(x + 1)$$\textrm{.}$', '["$1/(x^2 + 2x + 1)$", "$1/(x + 1)$", "$1$", "$2x/(x^2 + 2x + 1) + 1/(x^2 + 2x + 1)$"]'::jsonb, 0, '$\textrm{Quotient}$ $\textrm{Rule:}$ $(u/v)'' = \dfrac{u''v - uv''}{v^2}$$\textrm{.}$ $\textrm{With}$ $u = x$ $\textrm{and}$ $v = x + 1$$\textrm{:}$ $u'' = 1$ $\textrm{and}$ $v'' = 1$$\textrm{.}$ $\textrm{So}$ $f''(x)$ $=$ $\dfrac{u''v - uv''}{v^2}$ $=$ $\dfrac{(1)(x + 1) - (x)(1)}{(x + 1)^2}$ $=$ $\dfrac{1}{x^{2} + 2 x + 1}$$\textrm{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Quotient}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = (x^2)/(x - 2)$$\textrm{.}$', '["$x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)$", "$2x$", "$2x/(x - 2)$", "$3x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)$"]'::jsonb, 0, '$\textrm{Quotient}$ $\textrm{Rule:}$ $(u/v)'' = \dfrac{u''v - uv''}{v^2}$$\textrm{.}$ $\textrm{With}$ $u = x^{2}$ $\textrm{and}$ $v = x - 2$$\textrm{:}$ $u'' = 2 x$ $\textrm{and}$ $v'' = 1$$\textrm{.}$ $\textrm{So}$ $f''(x)$ $=$ $\dfrac{u''v - uv''}{v^2}$ $=$ $\dfrac{(2 x)(x - 2) - (x^{2})(1)}{(x - 2)^2}$ $=$ $\dfrac{x^{2} - 4 x}{x^{2} - 4 x + 4}$$\textrm{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Quotient}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = (\sin(x))/(x)$$\textrm{.}$', '["$(x \\cos(x) + \\sin(x))/x^2$", "$(x \\cos(x) - \\sin(x))/x^2$", "$\\cos(x)/x$", "$\\cos(x)$"]'::jsonb, 1, '$\textrm{Quotient}$ $\textrm{Rule:}$ $(u/v)'' = \dfrac{u''v - uv''}{v^2}$$\textrm{.}$ $\textrm{With}$ $u = \sin{\left(x \right)}$ $\textrm{and}$ $v = x$$\textrm{:}$ $u'' = \cos{\left(x \right)}$ $\textrm{and}$ $v'' = 1$$\textrm{.}$ $\textrm{So}$ $f''(x)$ $=$ $\dfrac{u''v - uv''}{v^2}$ $=$ $\dfrac{(\cos{\left(x \right)})(x) - (\sin{\left(x \right)})(1)}{(x)^2}$ $=$ $\dfrac{x \cos{\left(x \right)} - \sin{\left(x \right)}}{x^{2}}$$\textrm{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Quotient}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = (2x + 1)/(x^2 + 1)$$\textrm{.}$', '["$1/x$", "$-2x^2/(x^4 + 2x^2 + 1)$ $-$ $2x/(x^4 + 2x^2 + 1)$ $+$ $2/(x^4 + 2x^2 + 1)$", "$2/(x^2 + 1)$", "$6x^2/(x^4 + 2x^2 + 1)$ $+$ $2x/(x^4 + 2x^2 + 1)$ $+$ $2/(x^4 + 2x^2 + 1)$"]'::jsonb, 1, '$\textrm{Quotient}$ $\textrm{Rule:}$ $(u/v)'' = \dfrac{u''v - uv''}{v^2}$$\textrm{.}$ $\textrm{With}$ $u = 2 x + 1$ $\textrm{and}$ $v = x^{2} + 1$$\textrm{:}$ $u'' = 2$ $\textrm{and}$ $v'' = 2 x$$\textrm{.}$ $\textrm{So}$ $f''(x)$ $=$ $\dfrac{u''v - uv''}{v^2}$ $=$ $\dfrac{(2)(x^{2} + 1) - (2 x + 1)(2 x)}{(x^{2} + 1)^2}$ $=$ $\dfrac{- 2 x^{2} - 2 x + 2}{x^{4} + 2 x^{2} + 1}$$\textrm{.}$', 'Rules of Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Chain}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = (x^2 + 1)^3$$\textrm{.}$', '["$3x^4 + 6x^2 + 3$", "$6x^5 + 12x^3 + 6x$", "$8x^3$", "$6x^7 + 18x^5 + 18x^3 + 6x$"]'::jsonb, 1, '$\textrm{Chain}$ $\textrm{Rule:}$ $\textrm{with}$ $u = x^{2} + 1$$\textrm{,}$ $\dfrac{d}{dx}[u^{3}] = 3 u^{2} \cdot u''$$\textrm{.}$ $\textrm{Here}$ $u'' = 2 x$$\textrm{,}$ $\textrm{so}$ $f''(x)$ $=$ $3(x^{2} + 1)^{2} \cdot (2 x)$ $=$ $6 x^{5} + 12 x^{3} + 6 x$$\textrm{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Chain}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = (2x - 5)^4$$\textrm{.}$', '["$64x^3 - 480x^2 + 1200x - 1000$", "$16$", "$128x^4$ $-$ $1280x^3$ $+$ $4800x^2$ $-$ $8000x$ $+$ $5000$", "$32x^3 - 240x^2 + 600x - 500$"]'::jsonb, 0, '$\textrm{Chain}$ $\textrm{Rule:}$ $\textrm{with}$ $u = 2 x - 5$$\textrm{,}$ $\dfrac{d}{dx}[u^{4}] = 4 u^{3} \cdot u''$$\textrm{.}$ $\textrm{Here}$ $u'' = 2$$\textrm{,}$ $\textrm{so}$ $f''(x)$ $=$ $4(2 x - 5)^{3} \cdot (2)$ $=$ $64 x^{3} - 480 x^{2} + 1200 x - 1000$$\textrm{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{Chain}$ $\textrm{Rule,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = (x^3 - 2x)^2$$\textrm{.}$', '["$2x^3 - 4x$", "$9x^4 - 12x^2 + 4$", "$6x^5 - 16x^3 + 8x$", "$6x^8 - 28x^6 + 40x^4 - 16x^2$"]'::jsonb, 2, '$\textrm{Chain}$ $\textrm{Rule:}$ $\textrm{with}$ $u = x^{3} - 2 x$$\textrm{,}$ $\dfrac{d}{dx}[u^{2}] = 2 u^{1} \cdot u''$$\textrm{.}$ $\textrm{Here}$ $u'' = 3 x^{2} - 2$$\textrm{,}$ $\textrm{so}$ $f''(x)$ $=$ $2(x^{3} - 2 x)^{1} \cdot (3 x^{2} - 2)$ $=$ $6 x^{5} - 16 x^{3} + 8 x$$\textrm{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \sin(2x + 3)$$\textrm{.}$', '["$2 \\cos(2x + 3)$", "$\\cos(2x + 3)$", "$-2 \\cos(2x + 3)$", "$\\sin(2)$"]'::jsonb, 0, '$\textrm{Chain}$ $\textrm{Rule:}$ $\textrm{with}$ $u = 2 x + 3$$\textrm{,}$ $\dfrac{d}{dx}[\sin(u)]$ $=$ $\cos(u) \cdot u''$$\textrm{.}$ $\textrm{Here}$ $u'' = 2$$\textrm{,}$ $\textrm{so}$ $f''(x)$ $=$ $\cos(2 x + 3) \cdot (2)$ $=$ $2 \cos{\left(2 x + 3 \right)}$$\textrm{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \sin(x^2)$$\textrm{.}$', '["$-2x \\cos(x^2)$", "$\\sin(2x)$", "$\\cos(x^2)$", "$2x \\cos(x^2)$"]'::jsonb, 3, '$\textrm{Chain}$ $\textrm{Rule:}$ $\textrm{with}$ $u = x^{2}$$\textrm{,}$ $\dfrac{d}{dx}[\sin(u)]$ $=$ $\cos(u) \cdot u''$$\textrm{.}$ $\textrm{Here}$ $u'' = 2 x$$\textrm{,}$ $\textrm{so}$ $f''(x)$ $=$ $\cos(x^{2}) \cdot (2 x)$ $=$ $2 x \cos{\left(x^{2} \right)}$$\textrm{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \sin(3x - 1)$$\textrm{.}$', '["$\\cos(3x - 1)$", "$-3 \\cos(3x - 1)$", "$3 \\cos(3x - 1)$", "$\\sin(3)$"]'::jsonb, 2, '$\textrm{Chain}$ $\textrm{Rule:}$ $\textrm{with}$ $u = 3 x - 1$$\textrm{,}$ $\dfrac{d}{dx}[\sin(u)]$ $=$ $\cos(u) \cdot u''$$\textrm{.}$ $\textrm{Here}$ $u'' = 3$$\textrm{,}$ $\textrm{so}$ $f''(x)$ $=$ $\cos(3 x - 1) \cdot (3)$ $=$ $3 \cos{\left(3 x - 1 \right)}$$\textrm{.}$', 'The Chain Rule', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{slope}$ $\textrm{of}$ $\textrm{the}$ $\textrm{tangent}$ $\textrm{line}$ $\textrm{to}$ $y = x^2 - 4x + 3 at x = 1$$\textrm{.}$', '["$-2$", "$-1$", "$0$", "$2$"]'::jsonb, 0, '$\textrm{The}$ $\textrm{slope}$ $\textrm{is}$ $f''(1)$ $\textrm{where}$ $f''(x) = 2 x - 4$$\textrm{,}$ $\textrm{so}$ $f''(1) = 2 \cdot 1 - 4 = -2$$\textrm{.}$', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{slope}$ $\textrm{of}$ $\textrm{the}$ $\textrm{tangent}$ $\textrm{line}$ $\textrm{to}$ $y = x^3 - 3x at x = 2$$\textrm{.}$', '["$2$", "$11$", "$-9$", "$9$"]'::jsonb, 3, '$\textrm{The}$ $\textrm{slope}$ $\textrm{is}$ $f''(2)$ $\textrm{where}$ $f''(x) = 3 x^{2} - 3$$\textrm{,}$ $\textrm{so}$ $f''(2) = 3 \cdot 2^{2} - 3 = 9$$\textrm{.}$', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{slope}$ $\textrm{of}$ $\textrm{the}$ $\textrm{tangent}$ $\textrm{line}$ $\textrm{to}$ $y = 2x^2 + 1 at x = -1$$\textrm{.}$', '["$-4$", "$3$", "$-2$", "$4$"]'::jsonb, 0, '$\textrm{The}$ $\textrm{slope}$ $\textrm{is}$ $f''(-1)$ $\textrm{where}$ $f''(x) = 4 x$$\textrm{,}$ $\textrm{so}$ $f''(-1) = 4 \left(-1\right) = -4$$\textrm{.}$', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{slope}$ $\textrm{of}$ $\textrm{the}$ $\textrm{tangent}$ $\textrm{line}$ $\textrm{to}$ $y = x^2 at x = 3$$\textrm{.}$', '["$9$", "$6$", "$-6$", "$8$"]'::jsonb, 1, '$\textrm{The}$ $\textrm{slope}$ $\textrm{is}$ $f''(3)$ $\textrm{where}$ $f''(x) = 2 x$$\textrm{,}$ $\textrm{so}$ $f''(3) = 2 \cdot 3 = 6$$\textrm{.}$', 'The Derivative', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{If}$ $x^2$ $\textrm{+}$ $y^2$ $\textrm{=}$ $\textrm{25,}$ $\textrm{find}$ $\textrm{dy/dx}$ $\textrm{at}$ $\textrm{the}$ $\textrm{point}$ $\textrm{(3,4).}$', '["$4/3$", "$-4/3$", "$3/4$", "$-3/4$"]'::jsonb, 3, '$\textrm{Differentiate}$ $\textrm{both}$ $\textrm{sides}$ $\textrm{of}$ $x^{2} + y^{2} = 25$ $\textrm{implicitly}$ $\textrm{with}$ $\textrm{respect}$ $\textrm{to}$ $x$$\textrm{,}$ $\textrm{treating}$ $y$ $\textrm{as}$ $\textrm{a}$ $\textrm{function}$ $\textrm{of}$ $x$$\textrm{:}$ $2 x + 2 y(dy/dx) = 0$$\textrm{.}$ $\textrm{Solving}$ $\textrm{for}$ $dy/dx$$\textrm{:}$ $dy/dx = - \frac{x}{y}$$\textrm{.}$ $\textrm{At}$ $(3,4)$$\textrm{:}$ $dy/dx = - \frac{3}{4} = - \frac{3}{4}$$\textrm{.}$', 'Implicit Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{If}$ $x^3$ $\textrm{+}$ $y^3$ $\textrm{=}$ $\textrm{9,}$ $\textrm{find}$ $\textrm{dy/dx}$ $\textrm{at}$ $\textrm{the}$ $\textrm{point}$ $\textrm{(1,2).}$', '["$1/4$", "$-4$", "$4$", "$-1/4$"]'::jsonb, 3, '$\textrm{Differentiate}$ $\textrm{both}$ $\textrm{sides}$ $\textrm{of}$ $x^{3} + y^{3} = 9$ $\textrm{implicitly}$ $\textrm{with}$ $\textrm{respect}$ $\textrm{to}$ $x$$\textrm{,}$ $\textrm{treating}$ $y$ $\textrm{as}$ $\textrm{a}$ $\textrm{function}$ $\textrm{of}$ $x$$\textrm{:}$ $3 x^{2} + 3 y^{2}(dy/dx) = 0$$\textrm{.}$ $\textrm{Solving}$ $\textrm{for}$ $dy/dx$$\textrm{:}$ $dy/dx = - \frac{x^{2}}{y^{2}}$$\textrm{.}$ $\textrm{At}$ $(1,2)$$\textrm{:}$ $dy/dx = - \frac{1}{4} = - \frac{1}{4}$$\textrm{.}$', 'Implicit Differentiation', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{critical}$ $\textrm{point(s)}$ $\textrm{of}$ $f(x) = x^3 - 3x + 1$$\textrm{.}$', '["$0$", "$-1, 1$", "$\\textrm{no}$ $\\textrm{critical}$ $\\textrm{points}$", "$0, 2$"]'::jsonb, 1, '$f''(x) = 3 x^{2} - 3$$\textrm{.}$ $\textrm{Setting}$ $f''(x) = 0$$\textrm{:}$ $3 x^{2} - 3 = 0$$\textrm{,}$ $\textrm{which}$ $\textrm{gives}$ $x = -1, 1$$\textrm{.}$', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{critical}$ $\textrm{point(s)}$ $\textrm{of}$ $f(x) = x^2 - 6x + 5$$\textrm{.}$', '["$\\textrm{no}$ $\\textrm{critical}$ $\\textrm{points}$", "$3$", "$4$", "$2$"]'::jsonb, 1, '$f''(x) = 2 x - 6$$\textrm{.}$ $\textrm{Setting}$ $f''(x) = 0$$\textrm{:}$ $2 x - 6 = 0$$\textrm{,}$ $\textrm{which}$ $\textrm{gives}$ $x = 3$$\textrm{.}$', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{critical}$ $\textrm{point(s)}$ $\textrm{of}$ $f(x) = 2x^3 - 3x^2 - 12x + 4$$\textrm{.}$', '["$0, 3$", "$0$", "$\\textrm{no}$ $\\textrm{critical}$ $\\textrm{points}$", "$-1, 2$"]'::jsonb, 3, '$f''(x) = 6 x^{2} - 6 x - 12$$\textrm{.}$ $\textrm{Setting}$ $f''(x) = 0$$\textrm{:}$ $6 x^{2} - 6 x - 12 = 0$$\textrm{,}$ $\textrm{which}$ $\textrm{gives}$ $x = -1, 2$$\textrm{.}$', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{critical}$ $\textrm{point(s)}$ $\textrm{of}$ $f(x) = x^3 - 12x$$\textrm{.}$', '["$-2, 2$", "$-1, 3$", "$0$", "$\\textrm{no}$ $\\textrm{critical}$ $\\textrm{points}$"]'::jsonb, 0, '$f''(x) = 3 x^{2} - 12$$\textrm{.}$ $\textrm{Setting}$ $f''(x) = 0$$\textrm{:}$ $3 x^{2} - 12 = 0$$\textrm{,}$ $\textrm{which}$ $\textrm{gives}$ $x = -2, 2$$\textrm{.}$', 'Maxima and Minima', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{At}$ $\textrm{the}$ $\textrm{critical}$ $\textrm{point}$ $\textrm{x}$ $\textrm{=}$ $\textrm{1}$ $\textrm{of}$ $f(x) = x^3 - 3x$$\textrm{,}$ $\textrm{the}$ $\textrm{Second}$ $\textrm{Derivative}$ $\textrm{Test}$ $\textrm{shows}$ $\textrm{this}$ $\textrm{is}$ $\textrm{a:}$', '["$\\textrm{point}$ $\\textrm{of}$ $\\textrm{inflection}$", "$\\textrm{relative}$ $\\textrm{maximum}$", "$\\textrm{not}$ $\\textrm{a}$ $\\textrm{critical}$ $\\textrm{point}$", "$\\textrm{relative}$ $\\textrm{minimum}$"]'::jsonb, 3, '$f''''(x) = 6 x$$\textrm{,}$ $\textrm{so}$ $f''''(1) = 6 \cdot 1 = 6$$\textrm{,}$ $\textrm{which}$ $\textrm{is}$ $\textrm{positive,}$ $\textrm{indicating}$ $\textrm{a}$ $\textrm{relative}$ $\textrm{minimum.}$', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{At}$ $\textrm{the}$ $\textrm{critical}$ $\textrm{point}$ $\textrm{x}$ $\textrm{=}$ $\textrm{-1}$ $\textrm{of}$ $f(x) = x^3 - 3x$$\textrm{,}$ $\textrm{the}$ $\textrm{Second}$ $\textrm{Derivative}$ $\textrm{Test}$ $\textrm{shows}$ $\textrm{this}$ $\textrm{is}$ $\textrm{a:}$', '["$\\textrm{relative}$ $\\textrm{minimum}$", "$\\textrm{not}$ $\\textrm{a}$ $\\textrm{critical}$ $\\textrm{point}$", "$\\textrm{relative}$ $\\textrm{maximum}$", "$\\textrm{point}$ $\\textrm{of}$ $\\textrm{inflection}$"]'::jsonb, 2, '$f''''(x) = 6 x$$\textrm{,}$ $\textrm{so}$ $f''''(-1) = 6 \left(-1\right) = -6$$\textrm{,}$ $\textrm{which}$ $\textrm{is}$ $\textrm{negative,}$ $\textrm{indicating}$ $\textrm{a}$ $\textrm{relative}$ $\textrm{maximum.}$', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{At}$ $\textrm{the}$ $\textrm{critical}$ $\textrm{point}$ $\textrm{x}$ $\textrm{=}$ $\textrm{2}$ $\textrm{of}$ $f(x) = x^2 - 4x + 7$$\textrm{,}$ $\textrm{the}$ $\textrm{Second}$ $\textrm{Derivative}$ $\textrm{Test}$ $\textrm{shows}$ $\textrm{this}$ $\textrm{is}$ $\textrm{a:}$', '["$\\textrm{relative}$ $\\textrm{maximum}$", "$\\textrm{not}$ $\\textrm{a}$ $\\textrm{critical}$ $\\textrm{point}$", "$\\textrm{relative}$ $\\textrm{minimum}$", "$\\textrm{point}$ $\\textrm{of}$ $\\textrm{inflection}$"]'::jsonb, 2, '$f''''(x) = 2$$\textrm{,}$ $\textrm{so}$ $f''''(2) = 2 = 2$$\textrm{,}$ $\textrm{which}$ $\textrm{is}$ $\textrm{positive,}$ $\textrm{indicating}$ $\textrm{a}$ $\textrm{relative}$ $\textrm{minimum.}$', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{At}$ $\textrm{the}$ $\textrm{critical}$ $\textrm{point}$ $\textrm{x}$ $\textrm{=}$ $\textrm{3}$ $\textrm{of}$ $f(x) = -x^2 + 6x - 5$$\textrm{,}$ $\textrm{the}$ $\textrm{Second}$ $\textrm{Derivative}$ $\textrm{Test}$ $\textrm{shows}$ $\textrm{this}$ $\textrm{is}$ $\textrm{a:}$', '["$\\textrm{not}$ $\\textrm{a}$ $\\textrm{critical}$ $\\textrm{point}$", "$\\textrm{relative}$ $\\textrm{maximum}$", "$\\textrm{relative}$ $\\textrm{minimum}$", "$\\textrm{point}$ $\\textrm{of}$ $\\textrm{inflection}$"]'::jsonb, 1, '$f''''(x) = -2$$\textrm{,}$ $\textrm{so}$ $f''''(3) = -2 = -2$$\textrm{,}$ $\textrm{which}$ $\textrm{is}$ $\textrm{negative,}$ $\textrm{indicating}$ $\textrm{a}$ $\textrm{relative}$ $\textrm{maximum.}$', 'The Second Derivative Test for Extremum', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{For}$ $f(x) = x^2 - 4x + 3$$\textrm{,}$ $\textrm{on}$ $\textrm{which}$ $\textrm{interval}$ $\textrm{is}$ $\textrm{f}$ $\textrm{increasing?}$', '["$(2, \\infty)$", "$(-\\infty, \\infty)$", "$(0, 2)$", "$(-\\infty, 2)$"]'::jsonb, 0, '$f''(x) = 2 \left(x - 2\right)$$\textrm{.}$ $\textrm{Solving}$ $f''(x) > 0$ $\textrm{shows}$ $f''(x)$ $\textrm{is}$ $\textrm{positive}$ $\textrm{for}$ $x \in \left(2, \infty\right)$$\textrm{,}$ $\textrm{so}$ $f$ $\textrm{is}$ $\textrm{increasing}$ $\textrm{on}$ $\left(2, \infty\right)$$\textrm{.}$', 'Monotonicity of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{For}$ $f(x) = x^3 - 3x$$\textrm{,}$ $\textrm{on}$ $\textrm{which}$ $\textrm{interval}$ $\textrm{is}$ $\textrm{f}$ $\textrm{decreasing?}$', '["$(-\\infty, \\infty)$", "$(-\\infty,-1)$", "$(-1, 1)$", "$(1, \\infty)$"]'::jsonb, 2, '$f''(x)$ $=$ $3 \left(x - 1\right) \left(x + 1\right)$$\textrm{.}$ $\textrm{Solving}$ $f''(x) < 0$ $\textrm{shows}$ $f''(x)$ $\textrm{is}$ $\textrm{negative}$ $\textrm{for}$ $x \in \left(-1, 1\right)$$\textrm{,}$ $\textrm{so}$ $f$ $\textrm{is}$ $\textrm{decreasing}$ $\textrm{on}$ $\left(-1, 1\right)$$\textrm{.}$', 'Monotonicity of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{equation}$ $\textrm{of}$ $\textrm{the}$ $\textrm{tangent}$ $\textrm{line}$ $\textrm{to}$ $y = x^2 at x = -1$$\textrm{.}$', '["$y = -2x + 1$", "$y = -2x - 1$", "$y = 1x - 2$", "$y = 2x - 1$"]'::jsonb, 1, '$f(-1) = 1$$\textrm{,}$ $f''(-1) = -2$$\textrm{.}$ $\textrm{Using}$ $\textrm{the}$ $\textrm{point-slope}$ $\textrm{form}$ $y - f(a) = f''(a)(x-a)$$\textrm{:}$ $y - 1 = -2(x - -1)$$\textrm{,}$ $\textrm{which}$ $\textrm{simplifies}$ $\textrm{to}$ $y = -2x - 1$$\textrm{.}$', 'Tangents and Normals', false),
