  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\int_{1}^{4} 3x - 1 \, dx$$\textrm{.}$', '["$41/2$", "$-39/2$", "$20$", "$39/2$"]'::jsonb, 3, '$\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = \frac{3 x^{2}}{2} - x$$\textrm{.}$ $\textrm{By}$ $\textrm{the}$ $\textrm{Fundamental}$ $\textrm{Theorem,}$ $\int_{1}^{4} 3 x - 1 \, dx$ $=$ $F(4) - F(1)$ $=$ $(\frac{4 \left(-2 + 3 \cdot 4\right)}{2}$ $=$ $20)$ $-$ $(\frac{1 \left(-2 + 3 \cdot 1\right)}{2}$ $=$ $\frac{1}{2})$ $=$ $20 - \frac{1}{2}$ $=$ $\frac{39}{2}$$\textrm{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\int_{0}^{3} x^2 - 4x + 3 \, dx$$\textrm{.}$', '["$-1$", "$2$", "$0$", "$1$"]'::jsonb, 2, '$\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = \frac{x^{3}}{3} - 2 x^{2} + 3 x$$\textrm{.}$ $\textrm{By}$ $\textrm{the}$ $\textrm{Fundamental}$ $\textrm{Theorem,}$ $\int_{0}^{3} x^{2} - 4 x + 3 \, dx$ $=$ $F(3) - F(0)$ $=$ $(\frac{3 \left(9 - 6 \cdot 3 + 3^{2}\right)}{3}$ $=$ $0)$ $-$ $(\frac{0 \left(9 - 6 \cdot 0 + 0^{2}\right)}{3}$ $=$ $0)$ $=$ $0 - 0$ $=$ $0$$\textrm{.}$', 'Fundamental Theorem of Integral Calculus', false),
