  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\int_{-1}^{1} 4 - x^2 \, dx$$\textrm{.}$', '["$-22/3$", "$22/3$", "$25/3$", "$11/3$"]'::jsonb, 1, '$\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = - \frac{x^{3}}{3} + 4 x$$\textrm{.}$ $\textrm{By}$ $\textrm{the}$ $\textrm{Fundamental}$ $\textrm{Theorem,}$ $\int_{-1}^{1} 4 - x^{2} \, dx$ $=$ $F(1) - F(-1)$ $=$ $(\frac{1 \left(12 - 1^{2}\right)}{3}$ $=$ $\frac{11}{3})$ $-$ $(\frac{\left(-1\right) \left(12 - \left(-1\right)^{2}\right)}{3}$ $=$ $- \frac{11}{3})$ $=$ $\frac{11}{3} - - \frac{11}{3}$ $=$ $\frac{22}{3}$$\textrm{.}$', 'Fundamental Theorem of Integral Calculus', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{area}$ $\textrm{of}$ $\textrm{the}$ $\textrm{region}$ $\textrm{bounded}$ $\textrm{by}$ $y = x^2$$\textrm{,}$ $\textrm{the}$ $\textrm{x-axis,}$ $x=0$$\textrm{,}$ $\textrm{and}$ $\textrm{x=2.}$', '["$16/3$", "$11/3$", "$-8/3$", "$8/3$"]'::jsonb, 3, '$y=x^{2}$ $\textrm{does}$ $\textrm{not}$ $\textrm{cross}$ $\textrm{the}$ $x$$\textrm{-axis}$ $\textrm{between}$ $x=0$ $\textrm{and}$ $x=2$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $\int_{0}^{2} x^{2} \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = \frac{x^{3}}{3}$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $F(2) - F(0)$ $=$ $\frac{2^{3}}{3} - (\frac{0^{3}}{3})$ $=$ $\frac{8}{3}$$\textrm{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{area}$ $\textrm{of}$ $\textrm{the}$ $\textrm{region}$ $\textrm{bounded}$ $\textrm{by}$ $y = 3x$$\textrm{,}$ $\textrm{the}$ $\textrm{x-axis,}$ $x=0$$\textrm{,}$ $\textrm{and}$ $\textrm{x=4.}$', '["$-24$", "$25$", "$48$", "$24$"]'::jsonb, 3, '$y=3 x$ $\textrm{does}$ $\textrm{not}$ $\textrm{cross}$ $\textrm{the}$ $x$$\textrm{-axis}$ $\textrm{between}$ $x=0$ $\textrm{and}$ $x=4$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $\int_{0}^{4} 3 x \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = \frac{3 x^{2}}{2}$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $F(4) - F(0)$ $=$ $\frac{3 \cdot 4^{2}}{2}$ $-$ $(\frac{3 \cdot 0^{2}}{2})$ $=$ $24$$\textrm{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{area}$ $\textrm{of}$ $\textrm{the}$ $\textrm{region}$ $\textrm{bounded}$ $\textrm{by}$ $y = 4 - x^2$$\textrm{,}$ $\textrm{the}$ $\textrm{x-axis,}$ $x=-2$$\textrm{,}$ $\textrm{and}$ $\textrm{x=2.}$', '["$32/3$", "$-32/3$", "$35/3$", "$64/3$"]'::jsonb, 0, '$y=4 - x^{2}$ $\textrm{does}$ $\textrm{not}$ $\textrm{cross}$ $\textrm{the}$ $x$$\textrm{-axis}$ $\textrm{between}$ $x=-2$ $\textrm{and}$ $x=2$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $\int_{-2}^{2} 4 - x^{2} \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = - \frac{x^{3}}{3} + 4 x$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $F(2) - F(-2)$ $=$ $\frac{2 \left(12 - 2^{2}\right)}{3}$ $-$ $(\frac{\left(-2\right) \left(12 - \left(-2\right)^{2}\right)}{3})$ $=$ $\frac{32}{3}$$\textrm{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{area}$ $\textrm{of}$ $\textrm{the}$ $\textrm{region}$ $\textrm{bounded}$ $\textrm{by}$ $y = x^3$$\textrm{,}$ $\textrm{the}$ $\textrm{x-axis,}$ $x=0$$\textrm{,}$ $\textrm{and}$ $\textrm{x=2.}$', '["$8$", "$-4$", "$4$", "$5$"]'::jsonb, 2, '$y=x^{3}$ $\textrm{does}$ $\textrm{not}$ $\textrm{cross}$ $\textrm{the}$ $x$$\textrm{-axis}$ $\textrm{between}$ $x=0$ $\textrm{and}$ $x=2$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $\int_{0}^{2} x^{3} \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = \frac{x^{4}}{4}$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $F(2) - F(0)$ $=$ $\frac{2^{4}}{4} - (\frac{0^{4}}{4})$ $=$ $4$$\textrm{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{area}$ $\textrm{of}$ $\textrm{the}$ $\textrm{region}$ $\textrm{bounded}$ $\textrm{by}$ $y$ $=$ $x + 3 and y$ $=$ $x^2 - 1 between x$ $=$ $-1 and x$ $=$ $1$$\textrm{.}$', '["$6$", "$-22/3$", "$22/3$", "$28/3$"]'::jsonb, 2, '$\textrm{Between}$ $x=-1$ $\textrm{and}$ $x=1$$\textrm{,}$ $y=x + 3$ $\textrm{lies}$ $\textrm{above}$ $y=x^{2} - 1$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $\int_{-1}^{1} [(x + 3) - (x^{2} - 1)] \, dx$ $=$ $\int_{-1}^{1} - x^{2} + x + 4 \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x)$ $=$ $- \frac{x^{3}}{3}$ $+$ $\frac{x^{2}}{2}$ $+$ $4 x$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $F(1) - F(-1)$ $=$ $\frac{1 \left(24 + 3 \cdot 1 - 2 \cdot 1^{2}\right)}{6}$ $-$ $(\frac{\left(-1\right) \left(24 + 3 \left(-1\right) - 2 \left(-1\right)^{2}\right)}{6})$ $=$ $\frac{22}{3}$$\textrm{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{area}$ $\textrm{of}$ $\textrm{the}$ $\textrm{region}$ $\textrm{bounded}$ $\textrm{by}$ $y$ $=$ $6 - x and y$ $=$ $x^2 between x$ $=$ $-3 and x$ $=$ $2$$\textrm{.}$', '["$65/2$", "$-125/6$", "$137/6$", "$125/6$"]'::jsonb, 3, '$\textrm{Between}$ $x=-3$ $\textrm{and}$ $x=2$$\textrm{,}$ $y=6 - x$ $\textrm{lies}$ $\textrm{above}$ $y=x^{2}$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $\int_{-3}^{2} [(6 - x) - (x^{2})] \, dx$ $=$ $\int_{-3}^{2} - x^{2} - x + 6 \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x)$ $=$ $- \frac{x^{3}}{3}$ $-$ $\frac{x^{2}}{2}$ $+$ $6 x$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $F(2) - F(-3)$ $=$ $\frac{2 \left(36 - 3 \cdot 2 - 2 \cdot 2^{2}\right)}{6}$ $-$ $(\frac{\left(-3\right) \left(36 - 3 \left(-3\right) - 2 \left(-3\right)^{2}\right)}{6})$ $=$ $\frac{125}{6}$$\textrm{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{area}$ $\textrm{of}$ $\textrm{the}$ $\textrm{region}$ $\textrm{bounded}$ $\textrm{by}$ $y$ $=$ $x + 5 and y$ $=$ $x^2 - 1 between x$ $=$ $-2 and x$ $=$ $3$$\textrm{.}$', '["$137/6$", "$55/2$", "$-125/6$", "$125/6$"]'::jsonb, 3, '$\textrm{Between}$ $x=-2$ $\textrm{and}$ $x=3$$\textrm{,}$ $y=x + 5$ $\textrm{lies}$ $\textrm{above}$ $y=x^{2} - 1$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $\int_{-2}^{3} [(x + 5) - (x^{2} - 1)] \, dx$ $=$ $\int_{-2}^{3} - x^{2} + x + 6 \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x)$ $=$ $- \frac{x^{3}}{3}$ $+$ $\frac{x^{2}}{2}$ $+$ $6 x$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{area}$ $\textrm{is}$ $F(3) - F(-2)$ $=$ $\frac{3 \left(36 + 3 \cdot 3 - 2 \cdot 3^{2}\right)}{6}$ $-$ $(\frac{\left(-2\right) \left(36 + 3 \left(-2\right) - 2 \left(-2\right)^{2}\right)}{6})$ $=$ $\frac{125}{6}$$\textrm{.}$', 'Areas of Plane Regions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{disc}$ $\textrm{method,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{volume}$ $\textrm{of}$ $\textrm{the}$ $\textrm{solid}$ $\textrm{formed}$ $\textrm{by}$ $\textrm{revolving}$ $y = x$ $\textrm{about}$ $\textrm{the}$ $\textrm{x-axis}$ $\textrm{from}$ $\textrm{x=0}$ $\textrm{to}$ $\textrm{x=4.}$', '["$128\\pi/3$", "$-64\\pi/3$", "$8\\pi$", "$64\\pi/3$"]'::jsonb, 3, '$V$ $=$ $\pi \int_{0}^{4} [x]^2 \, dx$ $=$ $\pi \int_{0}^{4} x^{2} \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{of}$ $\textrm{the}$ $\textrm{integrand}$ $\textrm{is}$ $F(x) = \frac{x^{3}}{3}$$\textrm{,}$ $\textrm{so}$ $V$ $=$ $\pi \left[F(4) - F(0)\right]$ $=$ $\pi \left[\frac{4^{3}}{3} - \left(\frac{0^{3}}{3}\right)\right]$ $=$ $\frac{64 \pi}{3}$$\textrm{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{disc}$ $\textrm{method,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{volume}$ $\textrm{of}$ $\textrm{the}$ $\textrm{solid}$ $\textrm{formed}$ $\textrm{by}$ $\textrm{revolving}$ $y = \sqrt{x}$ $\textrm{about}$ $\textrm{the}$ $\textrm{x-axis}$ $\textrm{from}$ $\textrm{x=0}$ $\textrm{to}$ $\textrm{x=4.}$', '["$16\\pi$", "$8\\pi$", "$16\\pi/3$", "$-8\\pi$"]'::jsonb, 1, '$V$ $=$ $\pi \int_{0}^{4} [\sqrt{x}]^2 \, dx$ $=$ $\pi \int_{0}^{4} x \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{of}$ $\textrm{the}$ $\textrm{integrand}$ $\textrm{is}$ $F(x) = \frac{x^{2}}{2}$$\textrm{,}$ $\textrm{so}$ $V$ $=$ $\pi \left[F(4) - F(0)\right]$ $=$ $\pi \left[\frac{4^{2}}{2} - \left(\frac{0^{2}}{2}\right)\right]$ $=$ $8 \pi$$\textrm{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{disc}$ $\textrm{method,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{volume}$ $\textrm{of}$ $\textrm{the}$ $\textrm{solid}$ $\textrm{formed}$ $\textrm{by}$ $\textrm{revolving}$ $y = 2$ $\textrm{about}$ $\textrm{the}$ $\textrm{x-axis}$ $\textrm{from}$ $\textrm{x=0}$ $\textrm{to}$ $\textrm{x=3.}$', '["$12\\pi$", "$24\\pi$", "$-12\\pi$", "$6\\pi$"]'::jsonb, 0, '$V$ $=$ $\pi \int_{0}^{3} [2]^2 \, dx$ $=$ $\pi \int_{0}^{3} 4 \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{of}$ $\textrm{the}$ $\textrm{integrand}$ $\textrm{is}$ $F(x) = 4 x$$\textrm{,}$ $\textrm{so}$ $V$ $=$ $\pi \left[F(3) - F(0)\right]$ $=$ $\pi \left[4 \cdot 3 - \left(4 \cdot 0\right)\right]$ $=$ $12 \pi$$\textrm{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{disc}$ $\textrm{method,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{volume}$ $\textrm{of}$ $\textrm{the}$ $\textrm{solid}$ $\textrm{formed}$ $\textrm{by}$ $\textrm{revolving}$ $y = x^2$ $\textrm{about}$ $\textrm{the}$ $\textrm{x-axis}$ $\textrm{from}$ $\textrm{x=0}$ $\textrm{to}$ $\textrm{x=1.}$', '["$\\pi/3$", "$-\\pi/5$", "$2\\pi/5$", "$\\pi/5$"]'::jsonb, 3, '$V$ $=$ $\pi \int_{0}^{1} [x^{2}]^2 \, dx$ $=$ $\pi \int_{0}^{1} x^{4} \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{of}$ $\textrm{the}$ $\textrm{integrand}$ $\textrm{is}$ $F(x) = \frac{x^{5}}{5}$$\textrm{,}$ $\textrm{so}$ $V$ $=$ $\pi \left[F(1) - F(0)\right]$ $=$ $\pi \left[\frac{1^{5}}{5} - \left(\frac{0^{5}}{5}\right)\right]$ $=$ $\frac{\pi}{5}$$\textrm{.}$', 'The Disc Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \ln(3x^2 + 5)$$\textrm{.}$', '["$-6x/(3x^2 + 5)$", "$1/(3x^2 + 5)$", "$6x/(3x^2 + 5)$", "$6x$"]'::jsonb, 2, '$\textrm{By}$ $\textrm{the}$ $\textrm{Chain}$ $\textrm{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\textrm{.}$ $\textrm{With}$ $u = 3 x^{2} + 5$$\textrm{,}$ $u'' = 6 x$$\textrm{,}$ $\textrm{giving}$ $f''(x)$ $=$ $\dfrac{6 x}{3 x^{2} + 5}$ $=$ $\frac{6 x}{3 x^{2} + 5}$$\textrm{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \ln(\cos(x))$$\textrm{.}$', '["$1/\\cos(x)$", "$-\\sin(x)$", "$\\tan(x)$", "$-\\tan(x)$"]'::jsonb, 3, '$\textrm{By}$ $\textrm{the}$ $\textrm{Chain}$ $\textrm{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\textrm{.}$ $\textrm{With}$ $u = \cos{\left(x \right)}$$\textrm{,}$ $u'' = - \sin{\left(x \right)}$$\textrm{,}$ $\textrm{giving}$ $f''(x)$ $=$ $\dfrac{- \sin{\left(x \right)}}{\cos{\left(x \right)}}$ $=$ $- \tan{\left(x \right)}$$\textrm{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = \ln(x^3 - 2)$$\textrm{.}$', '["$1/(x^3 - 2)$", "$3x^2/(x^3 - 2)$", "$-3x^2/(x^3 - 2)$", "$3x^2$"]'::jsonb, 1, '$\textrm{By}$ $\textrm{the}$ $\textrm{Chain}$ $\textrm{Rule,}$ $\dfrac{d}{dx}[\ln(u)] = \dfrac{u''}{u}$$\textrm{.}$ $\textrm{With}$ $u = x^{3} - 2$$\textrm{,}$ $u'' = 3 x^{2}$$\textrm{,}$ $\textrm{giving}$ $f''(x)$ $=$ $\dfrac{3 x^{2}}{x^{3} - 2}$ $=$ $\frac{3 x^{2}}{x^{3} - 2}$$\textrm{.}$', 'The Natural Logarithmic Function', false),
