  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = e^{4x}$$\textrm{.}$', '["$-4e^{4x}$", "$4e^{4x}$", "$e^{4x}$", "$4$"]'::jsonb, 1, '$\textrm{By}$ $\textrm{the}$ $\textrm{Chain}$ $\textrm{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\textrm{.}$ $\textrm{With}$ $u = 4 x$$\textrm{,}$ $u'' = 4$$\textrm{,}$ $\textrm{giving}$ $f''(x) = e^{4 x} \cdot 4 = 4 e^{4 x}$$\textrm{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = e^{x^2}$$\textrm{.}$', '["$\\textrm{-2xe\\textasciicircum{}(x\\textasciicircum{}2)}$", "$2x$", "$\\textrm{2xe\\textasciicircum{}(x\\textasciicircum{}2)}$", "$e^{x^2}$"]'::jsonb, 2, '$\textrm{By}$ $\textrm{the}$ $\textrm{Chain}$ $\textrm{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\textrm{.}$ $\textrm{With}$ $u = x^{2}$$\textrm{,}$ $u'' = 2 x$$\textrm{,}$ $\textrm{giving}$ $f''(x)$ $=$ $e^{x^{2}} \cdot 2 x$ $=$ $2 x e^{x^{2}}$$\textrm{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{of}$ $f(x) = e^{\sin(x)}$$\textrm{.}$', '["$e^{\\sin(x)}$", "$\\cos(x)$", "$-e^{\\sin(x)}\\cos(x)$", "$e^{\\sin(x)}\\cos(x)$"]'::jsonb, 3, '$\textrm{By}$ $\textrm{the}$ $\textrm{Chain}$ $\textrm{Rule,}$ $\dfrac{d}{dx}[e^u] = e^u \cdot u''$$\textrm{.}$ $\textrm{With}$ $u = \sin{\left(x \right)}$$\textrm{,}$ $u'' = \cos{\left(x \right)}$$\textrm{,}$ $\textrm{giving}$ $f''(x)$ $=$ $e^{\sin{\left(x \right)}} \cdot \cos{\left(x \right)}$ $=$ $e^{\sin{\left(x \right)}} \cos{\left(x \right)}$$\textrm{.}$', 'The Exponential Function', false),
