  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{If}$ $f(x) = \ln(x^2 + 1)$$\textrm{,}$ $\textrm{find}$ $f''(2)$$\textrm{.}$', '["$4/3$", "$2/5$", "$1/5$", "$4/5$"]'::jsonb, 3, '$f''(x)$ $=$ $\dfrac{d}{dx}[\ln(u)]$ $=$ $\dfrac{u''}{u}$ $\textrm{with}$ $u = x^{2} + 1$$\textrm{:}$ $f''(x) = \frac{2 x}{x^{2} + 1}$$\textrm{.}$ $\textrm{At}$ $x=2$$\textrm{:}$ $f''(2)$ $=$ $\frac{2 \cdot 2}{2^{2} + 1}$ $=$ $\frac{4}{5}$$\textrm{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{If}$ $f(x) = e^{3x}$$\textrm{,}$ $\textrm{find}$ $f''(0)$$\textrm{.}$', '["$e^{3}$", "$0$", "$3$", "$1$"]'::jsonb, 2, '$f''(x)$ $=$ $\dfrac{d}{dx}[e^u]$ $=$ $e^u \cdot u''$ $\textrm{with}$ $u = 3 x$$\textrm{:}$ $f''(x) = 3 e^{3 x}$$\textrm{.}$ $\textrm{At}$ $x=0$$\textrm{:}$ $f''(0) = 3 e^{3 \cdot 0} = 3$$\textrm{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\int 1/x \, dx$$\textrm{.}$', '["$1/x^2 + C$", "$-1/x^2 + C$", "$ln|x| + C$", "$x \\cdot \\ln(x) + C$"]'::jsonb, 2, '$\textrm{With}$ $u = x$$\textrm{,}$ $du = 1 \, dx$$\textrm{.}$ $\int \dfrac{1}{x} \, dx$ $=$ $\int \dfrac{1}{u} \, du$ $=$ $\ln|u| + C$ $=$ $\ln|x| + C$$\textrm{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\int 2/(2x+1) \, dx$$\textrm{.}$', '["$2ln|2x+1| + C$", "$ln|x| + C$", "$(1/2)ln|2x+1| + C$", "$ln|2x+1| + C$"]'::jsonb, 3, '$\textrm{With}$ $u = 2 x + 1$$\textrm{,}$ $du = 2 \, dx$$\textrm{.}$ $\int \dfrac{2}{2 x + 1} \, dx$ $=$ $\int \dfrac{1}{u} \, du$ $=$ $\ln|u| + C$ $=$ $\ln|2 x + 1| + C$$\textrm{.}$', 'The Natural Logarithmic Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\int e^{5x} \, dx$$\textrm{.}$', '["$(1/5)e^{5x} + C$", "$5e^{5x} + C$", "$e^{5x} + C$", "$e^{5x}/x + C$"]'::jsonb, 0, '$\textrm{With}$ $u = 5 x$$\textrm{,}$ $du = 5 \, dx$$\textrm{.}$ $\int e^{5 x} \, dx$ $=$ $\dfrac{1}{5} \int e^u \, du$ $=$ $\dfrac{1}{5} e^u + C$ $=$ $\dfrac{1}{5} e^{5 x} + C$$\textrm{.}$', 'The Exponential Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{substitution,}$ $\textrm{find}$ $\int (3x + 5)^4 \, dx$$\textrm{.}$', '["$81x^5/5$ $+$ $135x^4$ $+$ $450x^3$ $+$ $750x^2$ $+$ $625x$ $+$ $C$", "$243x^5/5$ $+$ $405x^4$ $+$ $1350x^3$ $+$ $2250x^2$ $+$ $1875x$ $+$ $C$", "$-81x^5/5$ $-$ $135x^4$ $-$ $450x^3$ $-$ $750x^2$ $-$ $625x$ $+$ $C$", "$324x^3 + 1620x^2 + 2700x + 1500 + C$"]'::jsonb, 0, '$\textrm{Let}$ $u = 3 x + 5$$\textrm{,}$ $\textrm{so}$ $du = 3 \, dx$$\textrm{.}$ $\int \left(3 x + 5\right)^{4} \, dx$ $=$ $\dfrac{1}{3} \int u^{4} \, du$ $=$ $\dfrac{1}{3} \cdot \dfrac{u^{5}}{5} + C$$\textrm{.}$ $\textrm{Substituting}$ $\textrm{back}$ $u = 3 x + 5$ $\textrm{and}$ $\textrm{expanding:}$ $\int \left(3 x + 5\right)^{4} \, dx$ $=$ $\frac{81 x^{5}}{5}$ $+$ $135 x^{4}$ $+$ $450 x^{3}$ $+$ $750 x^{2}$ $+$ $625 x$ $+$ $C$$\textrm{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{substitution,}$ $\textrm{find}$ $\int \cos(2x + 1) \, dx$$\textrm{.}$', '["$-\\sin(2x + 1)/2 + C$", "$3 \\sin(2x + 1)/2 + C$", "$\\sin(2x + 1)/2 + C$", "$-2 \\sin(2x + 1) + C$"]'::jsonb, 2, '$\textrm{Let}$ $u = 2 x + 1$$\textrm{,}$ $\textrm{so}$ $du = 2 \, dx$$\textrm{.}$ $\int \cos(2 x + 1) \, dx$ $=$ $\dfrac{1}{2} \int \cos(u) \, du$ $=$ $\dfrac{1}{2} \sin(u) + C$$\textrm{.}$ $\textrm{Substituting}$ $\textrm{back}$ $u = 2 x + 1$$\textrm{:}$ $\int \cos(2 x + 1) \, dx$ $=$ $\frac{\sin{\left(2 x + 1 \right)}}{2}$ $+$ $C$$\textrm{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{substitution,}$ $\textrm{find}$ $\int (4 - 3x)^3 \, dx$$\textrm{.}$', '["$-81x^2 + 216x - 144 + C$", "$-81x^4/4 + 108x^3 - 216x^2 + 192x + C$", "$27x^4/4 - 36x^3 + 72x^2 - 64x + C$", "$-27x^4/4 + 36x^3 - 72x^2 + 64x + C$"]'::jsonb, 3, '$\textrm{Let}$ $u = 4 - 3 x$$\textrm{,}$ $\textrm{so}$ $du = -3 \, dx$$\textrm{.}$ $\int \left(4 - 3 x\right)^{3} \, dx$ $=$ $\dfrac{1}{-3} \int u^{3} \, du$ $=$ $\dfrac{1}{-3} \cdot \dfrac{u^{4}}{4} + C$$\textrm{.}$ $\textrm{Substituting}$ $\textrm{back}$ $u = 4 - 3 x$ $\textrm{and}$ $\textrm{expanding:}$ $\int \left(4 - 3 x\right)^{3} \, dx$ $=$ $- \frac{27 x^{4}}{4}$ $+$ $36 x^{3}$ $-$ $72 x^{2}$ $+$ $64 x$ $+$ $C$$\textrm{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{substitution,}$ $\textrm{find}$ $\int \sin(5x) \, dx$$\textrm{.}$', '["$-3 \\cos(5x)/5 + C$", "$-\\cos(5x)/5 + C$", "$\\cos(5x)/5 + C$", "$5 \\cos(5x) + C$"]'::jsonb, 1, '$\textrm{Using}$ $\textrm{an}$ $\textrm{appropriate}$ $\textrm{substitution}$ $\textrm{for}$ $\textrm{the}$ $\textrm{inner}$ $\textrm{expression,}$ $\int \sin{\left(5 x \right)} \, dx$ $=$ $- \frac{\cos{\left(5 x \right)}}{5} + C$$\textrm{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\int_{0}^{1} 2x(x^2 + 1)^3 \, dx$$\textrm{.}$', '["$15/4$", "$15/2$", "$-15/4$", "$19/4$"]'::jsonb, 0, '$\textrm{Using}$ $\textrm{substitution,}$ $\textrm{an}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x)$ $=$ $\frac{x^{8}}{4}$ $+$ $x^{6}$ $+$ $\frac{3 x^{4}}{2}$ $+$ $x^{2}$$\textrm{.}$ $\textrm{Evaluating}$ $\textrm{from}$ $x=0$ $\textrm{to}$ $x=1$$\textrm{:}$ $F(1) - F(0)$ $=$ $\frac{15}{4} - 0$ $=$ $\frac{15}{4}$$\textrm{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\int_{0}^{pi/2} \sin(x)^2 \cos(x) \, dx$$\textrm{.}$', '["$2/3$", "$1/3$", "$-1/3$", "$4/3$"]'::jsonb, 1, '$\textrm{Using}$ $\textrm{substitution,}$ $\textrm{an}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x)$ $=$ $\frac{\sin^{3}{\left(x \right)}}{3}$$\textrm{.}$ $\textrm{Evaluating}$ $\textrm{from}$ $x=0$ $\textrm{to}$ $x=\frac{\pi}{2}$$\textrm{:}$ $F(\frac{\pi}{2}) - F(0)$ $=$ $\frac{1}{3} - 0$ $=$ $\frac{1}{3}$$\textrm{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\int_{0}^{2} x/(x^2 + 4) \, dx$$\textrm{.}$', '["$3 \\log(2)/2$", "$-\\ln(2)/2$", "$\\ln(2)/2$", "$\\ln(2)$"]'::jsonb, 2, '$\textrm{Using}$ $\textrm{substitution,}$ $\textrm{an}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x)$ $=$ $\frac{\log{\left(x^{2} + 4 \right)}}{2}$$\textrm{.}$ $\textrm{Evaluating}$ $\textrm{from}$ $x=0$ $\textrm{to}$ $x=2$$\textrm{:}$ $F(2) - F(0)$ $=$ $\log{\left(2 \sqrt{2} \right)}$ $-$ $\log{\left(2 \right)}$ $=$ $\log{\left(\sqrt{2} \right)}$$\textrm{.}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{Integration}$ $\textrm{by}$ $\textrm{Parts,}$ $\textrm{find}$ $\int xe^{x} \, dx$$\textrm{.}$', '["$\\textrm{xe\\textasciicircum{}(x)}$ $\\textrm{+}$ $\\textrm{C}$", "$(1 - x)e^{x} + C$", "$(x - 1)e^{x} + C$", "$x^2e^{x}/2 + C$"]'::jsonb, 2, '$\textrm{With}$ $u = x$ $\textrm{and}$ $dv = e^{x} \, dx$$\textrm{:}$ $du = dx$ $\textrm{and}$ $v = e^{x}$$\textrm{.}$ $\textrm{Integration}$ $\textrm{by}$ $\textrm{parts,}$ $\int u \, dv = uv - \int v \, du$$\textrm{,}$ $\textrm{gives}$ $\int x e^{x} \, dx$ $=$ $xe^{x} - \int e^{x} \, dx$ $=$ $\left(x - 1\right) e^{x} + C$$\textrm{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{Integration}$ $\textrm{by}$ $\textrm{Parts,}$ $\textrm{find}$ $\int x \sin(x) \, dx$$\textrm{.}$', '["$-x \\cos(x) + \\sin(x) + C$", "$-x \\cos(x) + C$", "$-x^2 \\cos(x)/2 + C$", "$x \\cos(x) - \\sin(x) + C$"]'::jsonb, 0, '$\textrm{With}$ $u = x$ $\textrm{and}$ $dv = \sin{\left(x \right)} \, dx$$\textrm{:}$ $du = dx$ $\textrm{and}$ $v = - \cos{\left(x \right)}$$\textrm{.}$ $\textrm{Integration}$ $\textrm{by}$ $\textrm{parts,}$ $\int u \, dv = uv - \int v \, du$$\textrm{,}$ $\textrm{gives}$ $\int x \sin{\left(x \right)} \, dx$ $=$ $x- \cos{\left(x \right)}$ $-$ $\int$ $-$ $\cos{\left(x \right)} \, dx$ $=$ $- x \cos{\left(x \right)}$ $+$ $\sin{\left(x \right)}$ $+$ $C$$\textrm{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{Integration}$ $\textrm{by}$ $\textrm{Parts,}$ $\textrm{find}$ $\int x \cos(x) \, dx$$\textrm{.}$', '["$-x \\sin(x) - \\cos(x) + C$", "$x^2 \\sin(x)/2 + C$", "$x \\sin(x) + C$", "$x \\sin(x) + \\cos(x) + C$"]'::jsonb, 3, '$\textrm{With}$ $u = x$ $\textrm{and}$ $dv = \cos{\left(x \right)} \, dx$$\textrm{:}$ $du = dx$ $\textrm{and}$ $v = \sin{\left(x \right)}$$\textrm{.}$ $\textrm{Integration}$ $\textrm{by}$ $\textrm{parts,}$ $\int u \, dv = uv - \int v \, du$$\textrm{,}$ $\textrm{gives}$ $\int x \cos{\left(x \right)} \, dx$ $=$ $x\sin{\left(x \right)}$ $-$ $\int \sin{\left(x \right)} \, dx$ $=$ $x \sin{\left(x \right)}$ $+$ $\cos{\left(x \right)}$ $+$ $C$$\textrm{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Evaluate}$ $\int_{0}^{1} x \cdot e^x \, dx$$\textrm{.}$', '["$-1 + E$", "$\\textrm{E}$", "$0$", "$1$"]'::jsonb, 3, '$\textrm{Using}$ $\textrm{integration}$ $\textrm{by}$ $\textrm{parts}$ $\textrm{with}$ $u = x$$\textrm{,}$ $dv = e^{x} \, dx$$\textrm{:}$ $v = e^{x}$$\textrm{,}$ $\textrm{so}$ $\int x \, e^{x} \, dx$ $=$ $xe^{x} - \int e^{x} \, dx$ $=$ $\left(x - 1\right) e^{x} + C$$\textrm{.}$ $\textrm{Evaluating}$ $\textrm{from}$ $0$ $\textrm{to}$ $1$$\textrm{:}$ $(\left(-1 + 1\right) e^{1})$ $-$ $(\left(-1 + 0\right) e^{0})$ $=$ $0 - -1$ $=$ $1$$\textrm{.}$', 'Integration by Parts', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\int \tan(x) \, dx$$\textrm{.}$', '["$ln|\\sec(x)| + C$", "$ln|\\cos(x)| + C$", "$\\sec(x)\\tan(x) + C$", "$ln|\\sin(x)| + C$"]'::jsonb, 0, '$\textrm{Writing}$ $\tan(x) = \sin(x)/\cos(x)$ $\textrm{and}$ $\textrm{substituting}$ $v = \cos(x)$ $\textrm{(so}$ $dv = -\sin(x) \, dx$$\textrm{)}$ $\textrm{gives}$ $\int \tan(x) \, dx = -\ln|\cos(x)| + C$$\textrm{,}$ $\textrm{which}$ $\textrm{is}$ $\textrm{the}$ $\textrm{same}$ $\textrm{as}$ $\ln|\sec(x)| + C$ $\textrm{(since}$ $-\ln|\cos(x)|$ $=$ $\ln|\cos(x)|^{-1}$ $=$ $\ln|\sec(x)|$$\textrm{).}$', 'Method of Substitution', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Use}$ $\textrm{the}$ $\textrm{definition}$ $\textrm{of}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{(first}$ $\textrm{principles)}$ $\textrm{--}$ $\textrm{that}$ $\textrm{is,}$ $\textrm{f''(x)}$ $\textrm{as}$ $\textrm{the}$ $\textrm{limit,}$ $\textrm{as}$ $\textrm{h}$ $\textrm{approaches}$ $\textrm{0,}$ $\textrm{of}$ $\textrm{the}$ $\textrm{difference}$ $\textrm{quotient}$ $\textrm{[f(x+h)}$ $\textrm{-}$ $\textrm{f(x)]/h}$ $\textrm{--}$ $\textrm{to}$ $\textrm{find}$ $\textrm{f''(x)}$ $\textrm{for}$ $f(x) = x^2$$\textrm{.}$', '["$2x$", "$x^2$", "$2$", "$\\textrm{x}$"]'::jsonb, 0, '$\textrm{By}$ $\textrm{definition,}$ $f''(x)$ $=$ $\lim_{h \to 0} \dfrac{f(x+h) - f(x)}{h}$$\textrm{.}$ $\textrm{Here}$ $f(x+h) = (x+h)^2 = x^2 + 2xh + h^2$$\textrm{,}$ $\textrm{so}$ $\dfrac{f(x+h)-f(x)}{h}$ $=$ $\dfrac{2xh + h^2}{h}$ $=$ $2x + h$$\textrm{.}$ $\textrm{Letting}$ $h \to 0$ $\textrm{gives}$ $f''(x) = 2x$$\textrm{.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Use}$ $\textrm{the}$ $\textrm{definition}$ $\textrm{of}$ $\textrm{the}$ $\textrm{derivative}$ $\textrm{(first}$ $\textrm{principles)}$ $\textrm{to}$ $\textrm{find}$ $\textrm{f''(x)}$ $\textrm{for}$ $f(x) = 3x + 2$$\textrm{.}$', '["$3x$", "$2$", "$3$", "$0$"]'::jsonb, 2, '$f(x+h) = 3(x+h) + 2 = 3x + 3h + 2$$\textrm{,}$ $\textrm{so}$ $\dfrac{f(x+h) - f(x)}{h}$ $=$ $\dfrac{3h}{h}$ $=$ $3$ $\textrm{for}$ $\textrm{every}$ $h \neq 0$$\textrm{.}$ $\textrm{Letting}$ $h \to 0$$\textrm{,}$ $f''(x) = 3$ $\textrm{--}$ $\textrm{a}$ $\textrm{straight}$ $\textrm{line''s}$ $\textrm{slope}$ $\textrm{never}$ $\textrm{changes.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Use}$ $\textrm{first}$ $\textrm{principles}$ $\textrm{to}$ $\textrm{find}$ $\textrm{f''(x)}$ $\textrm{for}$ $f(x) = x^2 + 2x$$\textrm{,}$ $\textrm{then}$ $\textrm{evaluate}$ $f''(1)$$\textrm{.}$', '["$3$", "$4$", "$2$", "$1$"]'::jsonb, 1, '$f(x+h) - f(x)$ $=$ $(x+h)^{2} + 2(x+h) - x^{2} - 2x$ $=$ $2xh + h^{2} + 2h$$\textrm{,}$ $\textrm{so}$ $\dfrac{f(x+h)-f(x)}{h} = 2x + h + 2$$\textrm{.}$ $\textrm{Letting}$ $h \to 0$ $\textrm{gives}$ $f''(x) = 2x + 2$$\textrm{,}$ $\textrm{so}$ $f''(1) = 2(1) + 2 = 4$$\textrm{.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Use}$ $\textrm{first}$ $\textrm{principles}$ $\textrm{to}$ $\textrm{find}$ $\textrm{f''(x)}$ $\textrm{for}$ $f(x) = 1/x (x != 0)$$\textrm{.}$', '["$1/x^2$", "$-1/x^2$", "$-1/x$", "$1/x$"]'::jsonb, 1, '$\dfrac{f(x+h)-f(x)}{h}$ $=$ $\dfrac{1}{h}\left(\dfrac{1}{x+h} - \dfrac{1}{x}\right)$ $=$ $\dfrac{1}{h} \cdot \dfrac{x - (x+h)}{x(x+h)}$ $=$ $\dfrac{-h}{h \cdot x(x+h)}$ $=$ $\dfrac{-1}{x(x+h)}$$\textrm{.}$ $\textrm{Letting}$ $h \to 0$ $\textrm{gives}$ $f''(x) = -\dfrac{1}{x^{2}}$$\textrm{.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Use}$ $\textrm{first}$ $\textrm{principles}$ $\textrm{to}$ $\textrm{find}$ $\textrm{f''(x)}$ $\textrm{for}$ $f(x) = x^2 - 3x$$\textrm{,}$ $\textrm{then}$ $\textrm{evaluate}$ $f''(2)$$\textrm{.}$', '["$-1$", "$0$", "$1$", "$4$"]'::jsonb, 2, '$f(x+h) - f(x)$ $=$ $(x+h)^{2} - 3(x+h) - x^{2} + 3x$ $=$ $2xh + h^{2} - 3h$$\textrm{,}$ $\textrm{so}$ $\dfrac{f(x+h)-f(x)}{h} = 2x + h - 3$$\textrm{.}$ $\textrm{Letting}$ $h \to 0$ $\textrm{gives}$ $f''(x) = 2x - 3$$\textrm{,}$ $\textrm{so}$ $f''(2) = 2(2) - 3 = 1$$\textrm{.}$', 'The Derivative as a Limit', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{slope}$ $\textrm{of}$ $\textrm{the}$ $\textrm{line}$ $\textrm{tangent}$ $\textrm{to}$ $\textrm{the}$ $\textrm{curve}$ $y = x^3 at the point (1$$\textrm{,}$$1)$$\textrm{.}$', '["$1$", "$2$", "$3$", "$9$"]'::jsonb, 2, '$\textrm{The}$ $\textrm{slope}$ $\textrm{of}$ $\textrm{the}$ $\textrm{tangent}$ $\textrm{at}$ $x=x_0$ $\textrm{is}$ $y''(x_0)$$\textrm{.}$ $\textrm{Here}$ $y'' = 3x^{2}$$\textrm{,}$ $\textrm{so}$ $\textrm{at}$ $x_0=1$$\textrm{,}$ $\textrm{the}$ $\textrm{slope}$ $\textrm{is}$ $y''(1) = 3(1)^{2} = 3$$\textrm{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{equation}$ $\textrm{of}$ $\textrm{the}$ $\textrm{line}$ $\textrm{tangent}$ $\textrm{to}$ $\textrm{the}$ $\textrm{curve}$ $y = 3x^2 + 1 at the point (1$$\textrm{,}$$4)$$\textrm{.}$', '["$y = 6x - 2$", "$y = 3x + 1$", "$y = 6x + 4$", "$y = 2x + 2$"]'::jsonb, 0, '$y'' = 6x$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{slope}$ $\textrm{at}$ $(1,4)$ $\textrm{is}$ $y''(1) = 6$$\textrm{.}$ $\textrm{Using}$ $\textrm{the}$ $\textrm{point-slope}$ $\textrm{form}$ $y - y_0 = m(x - x_0)$ $\textrm{with}$ $m=6$$\textrm{,}$ $(x_0,y_0)=(1,4)$$\textrm{:}$ $y - 4 = 6(x - 1)$$\textrm{,}$ $\textrm{which}$ $\textrm{simplifies}$ $\textrm{to}$ $y = 6x - 2$$\textrm{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{equation}$ $\textrm{of}$ $\textrm{the}$ $\textrm{line}$ $\textrm{normal}$ $\textrm{to}$ $\textrm{the}$ $\textrm{curve}$ $y = x^3 + 1 at the point (-1$$\textrm{,}$$0)$$\textrm{.}$', '["$y = 3x + 3$", "$x + 3y = -1$", "$y = -3x - 3$", "$3x + y = -3$"]'::jsonb, 1, '$y'' = 3x^{2}$$\textrm{,}$ $\textrm{so}$ $\textrm{the}$ $\textrm{slope}$ $\textrm{of}$ $\textrm{the}$ $\textrm{tangent}$ $\textrm{at}$ $(-1,0)$ $\textrm{is}$ $y''(-1) = 3$$\textrm{.}$ $\textrm{The}$ $\textrm{normal}$ $\textrm{is}$ $\textrm{perpendicular}$ $\textrm{to}$ $\textrm{the}$ $\textrm{tangent,}$ $\textrm{so}$ $\textrm{its}$ $\textrm{slope}$ $\textrm{is}$ $-\dfrac{1}{3}$$\textrm{.}$ $\textrm{Using}$ $\textrm{point-slope}$ $\textrm{form:}$ $y - 0 = -\dfrac{1}{3}(x - (-1))$$\textrm{,}$ $\textrm{i.e.}$ $3y = -(x+1)$$\textrm{,}$ $\textrm{which}$ $\textrm{rearranges}$ $\textrm{to}$ $x + 3y = -1$$\textrm{.}$', 'Tangents and Normals', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{slope}$ $\textrm{of}$ $\textrm{the}$ $\textrm{tangent}$ $\textrm{to}$ $\textrm{the}$ $\textrm{curve}$ $y = x^2 - 4x + 3 at the point (3$$\textrm{,}$$0)$$\textrm{.}$', '["$-2$", "$0$", "$2$", "$3$"]'::jsonb, 2, '$y'' = 2x - 4$$\textrm{,}$ $\textrm{so}$ $\textrm{at}$ $x=3$ $\textrm{the}$ $\textrm{slope}$ $\textrm{is}$ $y''(3) = 2(3) - 4 = 2$$\textrm{.}$', 'Tangents and Normals', false),
