  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{If}$ $f(x) = 5x - 2$$\textrm{,}$ $\textrm{find}$ $f^{-1}(8)$$\textrm{.}$', '["$2$", "$3$", "$38$", "$1$"]'::jsonb, 0, '$\textrm{Set}$ $y = 5x-2$ $\textrm{and}$ $\textrm{solve}$ $\textrm{for}$ $x$$\textrm{:}$ $x = \dfrac{y+2}{5}$$\textrm{,}$ $\textrm{so}$ $f^{-1}(x) = \dfrac{x+2}{5}$$\textrm{.}$ $\textrm{Then}$ $f^{-1}(8)$ $=$ $\dfrac{8+2}{5}$ $=$ $\dfrac{10}{5}$ $=$ $2$$\textrm{.}$ $\textrm{(Check:}$ $f(2) = 5(2)-2 = 8$$\textrm{,}$ $\textrm{confirming}$ $\textrm{the}$ $\textrm{inverse.)}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{The}$ $\textrm{function}$ $f(x) = x^2$ $\textrm{for}$ $\textrm{x}$ $\textrm{>=}$ $\textrm{0}$ $\textrm{has}$ $\textrm{inverse}$ $f^{-1}(x) = \sqrt{x}$$\textrm{.}$ $\textrm{Find}$ $f^{-1}(9)$$\textrm{.}$', '["$3$", "$9$", "$81$", "$4.5$"]'::jsonb, 0, '$\textrm{Since}$ $f^{-1}(x) = \sqrt{x}$ $\textrm{for}$ $x \geq 0$$\textrm{,}$ $f^{-1}(9) = \sqrt{9} = 3$$\textrm{.}$ $\textrm{(Check:}$ $f(3) = 3^{2} = 9$$\textrm{,}$ $\textrm{confirming}$ $\textrm{the}$ $\textrm{inverse.)}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Find}$ $\textrm{the}$ $\textrm{inverse}$ $\textrm{of}$ $\textrm{the}$ $\textrm{function}$ $f(x) = (x + 1)/2$$\textrm{.}$', '["$f^{-1}(x) = 2x - 1$", "$f^{-1}(x) = 2x + 1$", "$f^{-1}(x) = (x-1)/2$", "$f^{-1}(x) = x/2 - 1$"]'::jsonb, 0, '$\textrm{Set}$ $y = \dfrac{x+1}{2}$ $\textrm{and}$ $\textrm{solve}$ $\textrm{for}$ $x$$\textrm{:}$ $2y = x+1$$\textrm{,}$ $\textrm{so}$ $x = 2y - 1$$\textrm{.}$ $\textrm{Swapping}$ $x$ $\textrm{and}$ $y$ $\textrm{gives}$ $f^{-1}(x) = 2x - 1$$\textrm{.}$', 'The Inverse of a Function', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{shell}$ $\textrm{method,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{volume}$ $\textrm{of}$ $\textrm{the}$ $\textrm{solid}$ $\textrm{formed}$ $\textrm{by}$ $\textrm{revolving}$ $\textrm{about}$ $\textrm{the}$ $\textrm{y-axis}$ $\textrm{the}$ $\textrm{region}$ $\textrm{under}$ $y = x^2 from x=0 to x=2$$\textrm{.}$', '["$8\\pi$", "$16\\pi/3$", "$4\\pi$", "$32\\pi/5$"]'::jsonb, 0, '$\textrm{By}$ $\textrm{the}$ $\textrm{shell}$ $\textrm{method,}$ $\textrm{revolving}$ $\textrm{about}$ $\textrm{the}$ $\textrm{y-axis}$ $\textrm{gives}$ $V$ $=$ $2\pi \int_{0}^{2} x \cdot f(x) \, dx$ $=$ $2\pi \int_{0}^{2} x \cdot x^{2} \, dx$ $=$ $2\pi \int_{0}^{2} x^{3} \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{of}$ $\textrm{the}$ $\textrm{integrand}$ $\textrm{is}$ $F(x) = \dfrac{x^{4}}{4}$$\textrm{,}$ $\textrm{so}$ $V$ $=$ $2\pi \left[F(2)-F(0)\right]$ $=$ $2\pi \left[\dfrac{16}{4} - 0\right]$ $=$ $2\pi(4)$ $=$ $8\pi$$\textrm{.}$', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{shell}$ $\textrm{method,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{volume}$ $\textrm{of}$ $\textrm{the}$ $\textrm{solid}$ $\textrm{formed}$ $\textrm{by}$ $\textrm{revolving}$ $\textrm{about}$ $\textrm{the}$ $\textrm{y-axis}$ $\textrm{the}$ $\textrm{region}$ $\textrm{under}$ $y = x from x=0 to x=3$$\textrm{.}$', '["$18\\pi$", "$9\\pi$", "$27\\pi$", "$6\\pi$"]'::jsonb, 0, '$V$ $=$ $2\pi \int_{0}^{3} x \cdot x \, dx$ $=$ $2\pi \int_{0}^{3} x^{2} \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = \dfrac{x^{3}}{3}$$\textrm{,}$ $\textrm{so}$ $V$ $=$ $2\pi \left[F(3)-F(0)\right]$ $=$ $2\pi \left[9 - 0\right]$ $=$ $18\pi$$\textrm{.}$', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{shell}$ $\textrm{method,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{volume}$ $\textrm{of}$ $\textrm{the}$ $\textrm{solid}$ $\textrm{formed}$ $\textrm{by}$ $\textrm{revolving}$ $\textrm{about}$ $\textrm{the}$ $\textrm{y-axis}$ $\textrm{the}$ $\textrm{region}$ $\textrm{under}$ $y = x^3 from x=0 to x=1$$\textrm{.}$', '["$2\\pi/5$", "$\\pi/4$", "$\\pi/3$", "$2\\pi/3$"]'::jsonb, 0, '$V$ $=$ $2\pi \int_{0}^{1} x \cdot x^{3} \, dx$ $=$ $2\pi \int_{0}^{1} x^{4} \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = \dfrac{x^{5}}{5}$$\textrm{,}$ $\textrm{so}$ $V$ $=$ $2\pi \left[F(1)-F(0)\right]$ $=$ $2\pi \left[\dfrac{1}{5} - 0\right]$ $=$ $\dfrac{2\pi}{5}$$\textrm{.}$', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{Using}$ $\textrm{the}$ $\textrm{shell}$ $\textrm{method,}$ $\textrm{find}$ $\textrm{the}$ $\textrm{volume}$ $\textrm{of}$ $\textrm{the}$ $\textrm{solid}$ $\textrm{formed}$ $\textrm{by}$ $\textrm{revolving}$ $\textrm{about}$ $\textrm{the}$ $\textrm{y-axis}$ $\textrm{the}$ $\textrm{region}$ $\textrm{under}$ $y = \sqrt{x} from x=0 to x=4$$\textrm{.}$', '["$128\\pi/5$", "$16\\pi$", "$64\\pi/3$", "$8\\pi$"]'::jsonb, 0, '$V$ $=$ $2\pi \int_{0}^{4} x \cdot \sqrt{x} \, dx$ $=$ $2\pi \int_{0}^{4} x^{3/2} \, dx$$\textrm{.}$ $\textrm{An}$ $\textrm{antiderivative}$ $\textrm{is}$ $F(x) = \dfrac{2}{5}x^{5/2}$$\textrm{,}$ $\textrm{so}$ $V$ $=$ $2\pi \left[F(4)-F(0)\right]$ $=$ $2\pi \left[\dfrac{2}{5}(32) - 0\right]$ $=$ $2\pi \cdot \dfrac{64}{5}$ $=$ $\dfrac{128\pi}{5}$$\textrm{.}$', 'The Shell Method', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{In}$ $\textrm{the}$ $\textrm{partial}$ $\textrm{fraction}$ $\textrm{decomposition}$ $\textrm{1/[(x-1)(x+1)]}$ $\textrm{=}$ $\textrm{A/(x-1)}$ $\textrm{+}$ $\textrm{B/(x+1),}$ $\textrm{find}$ $\textrm{A.}$', '["$1/2$", "$-1/2$", "$1$", "$-1$"]'::jsonb, 0, '$\textrm{Clearing}$ $\textrm{denominators:}$ $1 = A(x+1) + B(x-1)$$\textrm{.}$ $\textrm{Setting}$ $x=1$$\textrm{:}$ $1$ $=$ $A(2) + B(0) \Rightarrow A$ $=$ $\dfrac{1}{2}$$\textrm{.}$', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{In}$ $\textrm{the}$ $\textrm{partial}$ $\textrm{fraction}$ $\textrm{decomposition}$ $\textrm{1/[(x-1)(x+1)]}$ $\textrm{=}$ $\textrm{A/(x-1)}$ $\textrm{+}$ $\textrm{B/(x+1),}$ $\textrm{find}$ $\textrm{B.}$', '["$-1/2$", "$1/2$", "$1$", "$-1$"]'::jsonb, 0, '$\textrm{Clearing}$ $\textrm{denominators:}$ $1 = A(x+1) + B(x-1)$$\textrm{.}$ $\textrm{Setting}$ $x=-1$$\textrm{:}$ $1$ $=$ $A(0) + B(-2) \Rightarrow B$ $=$ $-\dfrac{1}{2}$$\textrm{.}$', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{In}$ $\textrm{the}$ $\textrm{partial}$ $\textrm{fraction}$ $\textrm{decomposition}$ $\textrm{5/[(x-2)(x+3)]}$ $\textrm{=}$ $\textrm{A/(x-2)}$ $\textrm{+}$ $\textrm{B/(x+3),}$ $\textrm{find}$ $\textrm{A}$ $\textrm{and}$ $\textrm{B.}$', '["$A = 1, B = -1$", "$A = 5, B = -5$", "$A = -1, B = 1$", "$A = 1, B = 1$"]'::jsonb, 0, '$\textrm{Clearing}$ $\textrm{denominators:}$ $5 = A(x+3) + B(x-2)$$\textrm{.}$ $\textrm{Setting}$ $x=2$$\textrm{:}$ $5 = A(5) \Rightarrow A=1$$\textrm{.}$ $\textrm{Setting}$ $x=-3$$\textrm{:}$ $5 = B(-5) \Rightarrow B=-1$$\textrm{.}$', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{In}$ $\textrm{the}$ $\textrm{partial}$ $\textrm{fraction}$ $\textrm{decomposition}$ $\textrm{(3x+1)/[(x-1)(x+2)]}$ $\textrm{=}$ $\textrm{A/(x-1)}$ $\textrm{+}$ $\textrm{B/(x+2),}$ $\textrm{find}$ $\textrm{A.}$', '["$4/3$", "$5/3$", "$3$", "$1$"]'::jsonb, 0, '$\textrm{Clearing}$ $\textrm{denominators:}$ $3x+1 = A(x+2) + B(x-1)$$\textrm{.}$ $\textrm{Setting}$ $x=1$$\textrm{:}$ $3(1)+1$ $=$ $A(3) \Rightarrow 4$ $=$ $3A \Rightarrow A$ $=$ $\dfrac{4}{3}$$\textrm{.}$', 'Method of Partial Fractions', false),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', '$\textrm{In}$ $\textrm{the}$ $\textrm{partial}$ $\textrm{fraction}$ $\textrm{decomposition}$ $\textrm{1/[x(x-1)\textasciicircum{}2]}$ $\textrm{=}$ $\textrm{A/x}$ $\textrm{+}$ $\textrm{B/(x-1)}$ $\textrm{+}$ $\textrm{C/(x-1)\textasciicircum{}2,}$ $\textrm{find}$ $\textrm{C}$ $\textrm{(the}$ $\textrm{coefficient}$ $\textrm{of}$ $\textrm{the}$ $\textrm{repeated-factor}$ $\textrm{term}$ $\textrm{1/(x-1)\textasciicircum{}2).}$', '["$1$", "$-1$", "$2$", "$0$"]'::jsonb, 0, '$\textrm{Clearing}$ $\textrm{denominators:}$ $1 = A(x-1)^{2} + Bx(x-1) + Cx$$\textrm{.}$ $\textrm{Setting}$ $x=1$ $\textrm{eliminates}$ $\textrm{the}$ $A$ $\textrm{and}$ $B$ $\textrm{terms:}$ $1 = A(0) + B(0) + C(1) \Rightarrow C = 1$$\textrm{.}$', 'Method of Partial Fractions', false);
